void ADFTypes::SAutoAimTuningData::read(IO::File& buffer) {
    tuning_id = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    tuning_file = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::SAutoAimTuningData::print(std::ostream &out) const {
    out << "tuning_id: " << tuning_id << "\n";
    out << "name: " << name << "\n";
    out << "tuning_file: " << tuning_file << "\n";
}

