void ADFTypes::CFOWControllerWeaponComponentData::read(IO::File& buffer) {
    ParentCWeaponComponentBase = std::move(Deferred::read(buffer));
    keep_missile_offset = buffer.read_pod<uint8>();
    buffer.skip(7);
    stop_targeting_player.read(buffer);
    missile_turn_speed = buffer.read_pod<float32>();
    missile_speed = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        idle_time_range[i] = buffer.read_pod<float32>();
    }
    fake_targeting_inner_radius = buffer.read_pod<float32>();
    cooldown_time = buffer.read_pod<float32>();
    locked_on_time = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        settlement_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        targeting_center[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    start_targeting_player.read(buffer);
    fake_targeting_outer_radius = buffer.read_pod<float32>();
    buffer.skip(4);
}

