void ADFTypes::VegetationEffect::read(IO::File& buffer) {
    BreakEffect.read(buffer);
    CollideEffect.read(buffer);
    PassThroughEffect.read(buffer);
    FastThroughEffect.read(buffer);
    for(int i = 0; i < 3; ++i) {
        BreakEffectOffset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        CollideEffectOffset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        PassThroughEffectOffset[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        BreakSound = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        CollideSound = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        PassThroughSound = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        FastThroughSound = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    FallingLeavesEffect.read(buffer);
    PassThroughSoundVolume = buffer.read_pod<int32>();
    FoliageDensity = buffer.read_pod<int32>();
    LocatorFile.read(buffer);
}

