void ADFTypes::CSoundModuleFMODEventData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    CSoundModuleSendFunctionArray.read(buffer);
    CSoundModuleFMODEventFunctionArray.read(buffer);
    SSoundModuleControllerAttachBone = std::move(Deferred::read(buffer));
    SSoundModuleControllerAttachPoint = std::move(Deferred::read(buffer));
    SSoundAcousticsProxy = std::move(Deferred::read(buffer));
    SSoundAddTagArray.read(buffer);
    SSoundAddTagsArray.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        module = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    static_ = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_on_created.read(buffer);
    event_create.read(buffer);
    _exportable = buffer.read_pod<int32>();
    buffer.skip(4);
    event_disable.read(buffer);
    parameter_update_urgency = buffer.read_pod<int32>();
    buffer.skip(4);
    event_enable.read(buffer);
    trigger_distance_disable = buffer.read_pod<float32>();
    release_on_disabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    occlusion_update_urgency = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        preset = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    create_on_enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    reverb_update_urgency = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    create_on_start = buffer.read_pod<uint8>();
    send_to_reverb = buffer.read_pod<uint8>();
    enabled = buffer.read_pod<uint8>();
    release_when_inactive = buffer.read_pod<uint8>();
    buffer.skip(4);
    event_release.read(buffer);
    trigger_distance_enable = buffer.read_pod<float32>();
    sound_occlusion = buffer.read_pod<int32>();
}

