void ADFTypes::WeaponTuning::read(IO::File& buffer) {
    missile_weapon.read(buffer);
    grenade_weapon.read(buffer);
    bullet_weapon.read(buffer);
    fow_weapon.read(buffer);
    clone_weapon.read(buffer);
    plasma_weapon.read(buffer);
    magazine_size = buffer.read_pod<int32>();
    max_range = buffer.read_pod<float32>();
    reload_time_scale = buffer.read_pod<float32>();
    velocity = buffer.read_pod<float32>();
    velocity_distance_scale_start = buffer.read_pod<float32>();
    velocity_distance_scale_end = buffer.read_pod<float32>();
    velocity_max = buffer.read_pod<float32>();
    fire_rate = buffer.read_pod<float32>();
    only_shoot_at_max_windup = buffer.read_pod<uint8>();
    force_fire_at_max_windup = buffer.read_pod<uint8>();
    fully_automatic_windup = buffer.read_pod<uint8>();
    block_windup_increase = buffer.read_pod<uint8>();
    fire_on_press = buffer.read_pod<uint8>();
    tuning_file_is_passive = buffer.read_pod<uint8>();
    fire_on_release = buffer.read_pod<uint8>();
    clear_windup_after_shot = buffer.read_pod<uint8>();
    time_to_max_windup = buffer.read_pod<float32>();
    windup_decline_multiplier = buffer.read_pod<float32>();
    initial_fire_rate_before_optimal = buffer.read_pod<float32>();
    burst_count = buffer.read_pod<uint8>();
    buffer.skip(3);
    burst_cooldown = buffer.read_pod<float32>();
    fully_automatic = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 2; ++i) {
        trigger_sensitivity[i] = buffer.read_pod<float32>();
    }
    aim_timer_override = buffer.read_pod<float32>();
    should_fire_clone_factory = buffer.read_pod<uint8>();
    should_fire_clone_factory_exclusively = buffer.read_pod<uint8>();
    buffer.skip(2);
    factory_index = buffer.read_pod<int32>();
    launch_speed = buffer.read_pod<float32>();
    UISettings.read(buffer);
    unlimited_ammo = buffer.read_pod<uint8>();
    consumes_ammo = buffer.read_pod<uint8>();
    buffer.skip(2);
    skip_fire_at_num_projectile_min = buffer.read_pod<int32>();
    skip_fire_at_num_projectile_max = buffer.read_pod<int32>();
    skip_fire_number_of_projectiles_skipped = buffer.read_pod<int32>();
    vehicle_energy_cost = buffer.read_pod<float32>();
    OverheatSettings.read(buffer);
    windup_rumble_scales = buffer.read_pod<uint8>();
    buffer.skip(3);
    windup_rumble.read(buffer);
    buffer.skip(4);
}

