void ADFTypes::CLaserLineData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    manual_control = buffer.read_pod<uint8>();
    buffer.skip(3);
    strength = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        end[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 4; ++i) {
        color[i] = buffer.read_pod<float32>();
    }
    HideEvent.read(buffer);
    enabled_on_creation = buffer.read_pod<uint8>();
    follow_parent = buffer.read_pod<uint8>();
    buffer.skip(2);
    for(int i = 0; i < 3; ++i) {
        start[i] = buffer.read_pod<float32>();
    }
    ShowEvent.read(buffer);
    OnHitEvent.read(buffer);
}

void ADFTypes::CLaserLineData::print(std::ostream &out) const {
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "manual_control: " << manual_control << "\n";
    out << "strength: " << strength << "\n";
    out << "end: \n";
    end.print(out);
    out << "\n";
    out << "name: " << name << "\n";
    out << "color: \n";
    color.print(out);
    out << "\n";
    HideEvent.print(out);
    out << "enabled_on_creation: " << enabled_on_creation << "\n";
    out << "follow_parent: " << follow_parent << "\n";
    out << "start: \n";
    start.print(out);
    out << "\n";
    ShowEvent.print(out);
    OnHitEvent.print(out);
}

nlohmann::json ADFTypes::CLaserLineData::to_json() const {
    nlohmann::json _res;
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["manual_control"] = manual_control;
    _res["strength"] = strength;
    _res["end"] = end.to_json();
    _res["name"] = name;
    _res["color"] = color.to_json();
    _res["HideEvent"] = HideEvent.to_json();
    _res["enabled_on_creation"] = enabled_on_creation;
    _res["follow_parent"] = follow_parent;
    _res["start"] = start.to_json();
    _res["ShowEvent"] = ShowEvent.to_json();
    _res["OnHitEvent"] = OnHitEvent.to_json();
    return _res;
}

