void ADFTypes::CElectricalConduitData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    preview_arcs = buffer.read_pod<uint8>();
    buffer.skip(3);
    allowed_arc_distance = buffer.read_pod<float32>();
    charge_given_per_arc = buffer.read_pod<float32>();
    buffer.skip(4);
    enable_event.read(buffer);
    stop_being_source_event.read(buffer);
    start_as_sink = buffer.read_pod<uint8>();
    buffer.skip(7);
    on_capacitor_filled_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        ignore_arc_damage_tag = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    duration = buffer.read_pod<float32>();
    no_long_paths = buffer.read_pod<uint8>();
    buffer.skip(3);
    max_capacitor_size = buffer.read_pod<float32>();
    buffer.skip(4);
    stop_being_conduit_event.read(buffer);
    capacitor_filled_threshold = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        spell_id_refire = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_conduit_arc_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        blackboard_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    start_being_source_event.read(buffer);
    refire_time_max = buffer.read_pod<float32>();
    refire_time_min = buffer.read_pod<float32>();
    disable_event.read(buffer);
    capacitor_emptied_threshold = buffer.read_pod<float32>();
    start_as_source = buffer.read_pod<uint8>();
    buffer.skip(3);
    clone_factory_ref.read(buffer);
    on_source_arc_event.read(buffer);
    start_as_conduit = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        spell_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_sink_arc_event.read(buffer);
    start_being_sink_event.read(buffer);
    tags_match_is_optional = buffer.read_pod<uint8>();
    buffer.skip(7);
    on_capacitor_emptied_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    capacitor_drain_rate = buffer.read_pod<float32>();
    start_enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    damage_refire_interval = buffer.read_pod<float32>();
    buffer.skip(4);
    stop_being_sink_event.read(buffer);
    start_being_conduit_event.read(buffer);
}

