void ADFTypes::SMetaDataCharacterDefinitionData::read(IO::File& buffer) {
    ParentCBackendCatalogItem = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    SMetaDataItemSlotArray.read(buffer);
    SMetaDataCharacterAbilityArray.read(buffer);
    SMetaDataCosmeticItemArray.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        portrait_url = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    display_name = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        hud_portrait_url = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    rarity = buffer.read_pod<int32>();
    buffer.skip(4);
    class_ref.read(buffer);
    full_name = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        character_tag_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    character_index = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        class_icon_url = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    description = buffer.read_pod<uint32>();
    buffer.skip(4);
}

