void ADFTypes::CBookMarkData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        color[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    completed.read(buffer);
    activated.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        note = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    hold_loading_screen = buffer.read_pod<uint8>();
    buffer.skip(7);
    loaded.read(buffer);
    type = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::CBookMarkData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "name: " << name << "\n";
    out << "color: \n";
    color.print(out);
    out << "\n";
    completed.print(out);
    activated.print(out);
    out << "note: " << note << "\n";
    out << "hold_loading_screen: " << hold_loading_screen << "\n";
    loaded.print(out);
    out << "type: " << type << "\n";
}

nlohmann::json ADFTypes::CBookMarkData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    _res["name"] = name;
    _res["color"] = color.to_json();
    _res["completed"] = completed.to_json();
    _res["activated"] = activated.to_json();
    _res["note"] = note;
    _res["hold_loading_screen"] = hold_loading_screen;
    _res["loaded"] = loaded.to_json();
    _res["type"] = type;
    return _res;
}

