void ADFTypes::CSpeakerData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    fade_in_time = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_enable.read(buffer);
    fade_out_time = buffer.read_pod<float32>();
    volume_max_speed = buffer.read_pod<float32>();
    energy = buffer.read_pod<float32>();
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    sound_object.read(buffer);
    one_shot = buffer.read_pod<uint8>();
    buffer.skip(3);
    near_distance_fade = buffer.read_pod<float32>();
    event_disable.read(buffer);
    enable_with_parent = buffer.read_pod<uint8>();
    buffer.skip(7);
    sound_object_alias.read(buffer);
}

void ADFTypes::CSpeakerData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCScaleTransformable: " << "\n";
    if (ParentCScaleTransformable) {
        ParentCScaleTransformable->print(out);
    }
    out << "fade_in_time: " << fade_in_time << "\n";
    out << "name: " << name << "\n";
    event_enable.print(out);
    out << "fade_out_time: " << fade_out_time << "\n";
    out << "volume_max_speed: " << volume_max_speed << "\n";
    out << "energy: " << energy << "\n";
    out << "enabled: " << enabled << "\n";
    sound_object.print(out);
    out << "one_shot: " << one_shot << "\n";
    out << "near_distance_fade: " << near_distance_fade << "\n";
    event_disable.print(out);
    out << "enable_with_parent: " << enable_with_parent << "\n";
    sound_object_alias.print(out);
}

nlohmann::json ADFTypes::CSpeakerData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCScaleTransformable) {
        _res["ParentCScaleTransformable"] = ParentCScaleTransformable->to_json();
    }
    _res["fade_in_time"] = fade_in_time;
    _res["name"] = name;
    _res["event_enable"] = event_enable.to_json();
    _res["fade_out_time"] = fade_out_time;
    _res["volume_max_speed"] = volume_max_speed;
    _res["energy"] = energy;
    _res["enabled"] = enabled;
    _res["sound_object"] = sound_object.to_json();
    _res["one_shot"] = one_shot;
    _res["near_distance_fade"] = near_distance_fade;
    _res["event_disable"] = event_disable.to_json();
    _res["enable_with_parent"] = enable_with_parent;
    _res["sound_object_alias"] = sound_object_alias.to_json();
    return _res;
}

