    scatter_first_shot_override_min = buffer.read_pod<float32>();
    scatter_minimum = buffer.read_pod<float32>();
    scatter_maximum = buffer.read_pod<float32>();
    scatter_per_shot = buffer.read_pod<float32>();
    scatter_multiplier_movement = buffer.read_pod<float32>();
    scatter_multiplier_aiming = buffer.read_pod<float32>();
    scatter_recover_rate = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        scatter_clamp_horizontal[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        scatter_clamp_vertical[i] = buffer.read_pod<float32>();
    }
    scatter_cone_cutoff = buffer.read_pod<float32>();
