void ADFTypes::CRopeObjectData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    interaction_context.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        diffuse_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    segments = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        normal_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 2; ++i) {
        texture_tiling[i] = buffer.read_pod<float32>();
    }
    radius = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        properties_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::CRopeObjectData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "name: " << name << "\n";
    interaction_context.print(out);
    out << "diffuse_texture: " << diffuse_texture << "\n";
    out << "segments: " << segments << "\n";
    out << "normal_texture: " << normal_texture << "\n";
    out << "texture_tiling: \n";
    texture_tiling.print(out);
    out << "\n";
    out << "radius: " << radius << "\n";
    out << "properties_texture: " << properties_texture << "\n";
}

nlohmann::json ADFTypes::CRopeObjectData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    _res["name"] = name;
    _res["interaction_context"] = interaction_context.to_json();
    _res["diffuse_texture"] = diffuse_texture;
    _res["segments"] = segments;
    _res["normal_texture"] = normal_texture;
    _res["texture_tiling"] = texture_tiling.to_json();
    _res["radius"] = radius;
    _res["properties_texture"] = properties_texture;
    return _res;
}

