void ADFTypes::CGasCanisterData::read(IO::File& buffer) {
    ParentCTransformObject = std::move(Deferred::read(buffer));
    enable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    gas_time_at_full_size = buffer.read_pod<float32>();
    faction = buffer.read_pod<int32>();
    on_gas_full.read(buffer);
    gas_start_delay = buffer.read_pod<float32>();
    gas_time_to_full_size = buffer.read_pod<float32>();
    disable.read(buffer);
    damage_type = buffer.read_pod<int32>();
    buffer.skip(4);
    on_gas_fade_start.read(buffer);
    on_gas_begin.read(buffer);
    gas_damage_per_sec = buffer.read_pod<int32>();
    buffer.skip(4);
    on_gas_fade_end.read(buffer);
    gas_time_to_fade = buffer.read_pod<float32>();
    gas_max_radius = buffer.read_pod<float32>();
}

void ADFTypes::CGasCanisterData::print(std::ostream &out) const {
    out << "ParentCTransformObject: " << "\n";
    if (ParentCTransformObject) {
        ParentCTransformObject->print(out);
    }
    enable.print(out);
    out << "name: " << name << "\n";
    out << "gas_time_at_full_size: " << gas_time_at_full_size << "\n";
    out << "faction: " << faction << "\n";
    on_gas_full.print(out);
    out << "gas_start_delay: " << gas_start_delay << "\n";
    out << "gas_time_to_full_size: " << gas_time_to_full_size << "\n";
    disable.print(out);
    out << "damage_type: " << damage_type << "\n";
    on_gas_fade_start.print(out);
    on_gas_begin.print(out);
    out << "gas_damage_per_sec: " << gas_damage_per_sec << "\n";
    on_gas_fade_end.print(out);
    out << "gas_time_to_fade: " << gas_time_to_fade << "\n";
    out << "gas_max_radius: " << gas_max_radius << "\n";
}

