void ADFTypes::CDynUIData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    show_quad = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        movie_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    movie_alpha = buffer.read_pod<float32>();
    sampler_index = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        quad_size[i] = buffer.read_pod<float32>();
    }
    texture_height = buffer.read_pod<int32>();
    deactivation_event.read(buffer);
    activation_event.read(buffer);
    texture_width = buffer.read_pod<int32>();
    has_code_interface = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 3; ++i) {
        movie_color[i] = buffer.read_pod<float32>();
    }
    movie_aa = buffer.read_pod<uint8>();
    buffer.skip(3);
    do_hide_event.read(buffer);
    movie_scale = buffer.read_pod<int32>();
    buffer.skip(4);
    do_show_event.read(buffer);
    clear_texture = buffer.read_pod<uint8>();
    buffer.skip(7);
}

