void ADFTypes::TerrainQuad::read(IO::File& buffer) {
    for(int i = 0; i < 4; ++i) {
        CornerIndices[i] = buffer.read_pod<int32>();
    }
    for(int i = 0; i < 4; ++i) {
        MidEdgeIndices[i] = buffer.read_pod<int32>();
    }
    for(int i = 0; i < 4; ++i) {
        NeighborHalfEdgeRes[i] = buffer.read_pod<uint8>();
    }
    for(int i = 0; i < 4; ++i) {
        NeighborHalfTexelDensity[i] = buffer.read_pod<uint8>();
    }
    LogSize = buffer.read_pod<int32>();
    LogTexelDensity = buffer.read_pod<int32>();
    MinS = buffer.read_pod<int32>();
    MinT = buffer.read_pod<int32>();
    Flags = buffer.read_pod<uint32>();
}

