void ADFTypes::CSoundOcclusionTerrainPlaneData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    height_offset = buffer.read_pod<float32>();
    attach_to_listener = buffer.read_pod<uint8>();
    inverted_normal = buffer.read_pod<uint8>();
    buffer.skip(2);
    occlusion_direct_path = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_enable.read(buffer);
    resolution = buffer.read_pod<int32>();
    buffer.skip(4);
    event_receive_matrix.read(buffer);
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    max_resolution = buffer.read_pod<int32>();
    bend_offset = buffer.read_pod<float32>();
    occlusion_reverb_mix = buffer.read_pod<float32>();
    _exportable = buffer.read_pod<int32>();
    attach_to_vegetation = buffer.read_pod<uint8>();
    buffer.skip(3);
    event_disable.read(buffer);
    double_sided = buffer.read_pod<uint8>();
    buffer.skip(7);
}

void ADFTypes::CSoundOcclusionTerrainPlaneData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCScaleTransformable: " << "\n";
    if (ParentCScaleTransformable) {
        ParentCScaleTransformable->print(out);
    }
    out << "height_offset: " << height_offset << "\n";
    out << "attach_to_listener: " << attach_to_listener << "\n";
    out << "inverted_normal: " << inverted_normal << "\n";
    out << "occlusion_direct_path: " << occlusion_direct_path << "\n";
    out << "name: " << name << "\n";
    event_enable.print(out);
    out << "resolution: " << resolution << "\n";
    event_receive_matrix.print(out);
    out << "enabled: " << enabled << "\n";
    out << "max_resolution: " << max_resolution << "\n";
    out << "bend_offset: " << bend_offset << "\n";
    out << "occlusion_reverb_mix: " << occlusion_reverb_mix << "\n";
    out << "_exportable: " << _exportable << "\n";
    out << "attach_to_vegetation: " << attach_to_vegetation << "\n";
    event_disable.print(out);
    out << "double_sided: " << double_sided << "\n";
}

nlohmann::json ADFTypes::CSoundOcclusionTerrainPlaneData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCScaleTransformable) {
        _res["ParentCScaleTransformable"] = ParentCScaleTransformable->to_json();
    }
    _res["height_offset"] = height_offset;
    _res["attach_to_listener"] = attach_to_listener;
    _res["inverted_normal"] = inverted_normal;
    _res["occlusion_direct_path"] = occlusion_direct_path;
    _res["name"] = name;
    _res["event_enable"] = event_enable.to_json();
    _res["resolution"] = resolution;
    _res["event_receive_matrix"] = event_receive_matrix.to_json();
    _res["enabled"] = enabled;
    _res["max_resolution"] = max_resolution;
    _res["bend_offset"] = bend_offset;
    _res["occlusion_reverb_mix"] = occlusion_reverb_mix;
    _res["_exportable"] = _exportable;
    _res["attach_to_vegetation"] = attach_to_vegetation;
    _res["event_disable"] = event_disable.to_json();
    _res["double_sided"] = double_sided;
    return _res;
}

