void ADFTypes::CMaterialPrimitiveBitmapData::read(IO::File& buffer) {
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    ParentCEditorObject = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        bitmap_path = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        material_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _distance_texture_width = buffer.read_pod<int32>();
    buffer.skip(4);
    _projection.read(buffer);
    for(int i = 0; i < 3; ++i) {
        _camera_position[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    _distance_texture.read(buffer);
}

