void ADFTypes::CUpgradeNodeData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    Parent_CSaveInfo = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    CUpgradeConstitutionHealthRegainArray.read(buffer);
    CUpgradeConstitutionDamageResistanceArray.read(buffer);
    CUpgradeConstitutionFeltriteAbsorptionArray.read(buffer);
    CUpgradeFallDamageArray.read(buffer);
    CUpgradeAfflictionResistanceArray.read(buffer);
    CUpgradeNodeLevelIncreaseArray.read(buffer);
    CUpgradeConstitutionRegenStrengthArray.read(buffer);
    CUpgradeOverdriveHealingArray.read(buffer);
    gui_name = buffer.read_pod<uint32>();
    max_upgrade_level = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    gui_description_lvl1 = buffer.read_pod<uint32>();
    always_unlocked = buffer.read_pod<uint8>();
    buffer.skip(3);
    gui_description = buffer.read_pod<uint32>();
    required_tier = buffer.read_pod<int32>();
    unlocked_event.read(buffer);
    is_tier_increase_node = buffer.read_pod<uint8>();
    buffer.skip(3);
    gui_name_lvl1 = buffer.read_pod<uint32>();
    save = buffer.read_pod<uint8>();
    buffer.skip(7);
}

