void ADFTypes::CTargetObjectData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    override_faction = buffer.read_pod<uint8>();
    buffer.skip(3);
    strength = buffer.read_pod<float32>();
    enable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    faction = buffer.read_pod<int32>();
    target_through_parent = buffer.read_pod<uint8>();
    buffer.skip(3);
    disruption_distance_override = buffer.read_pod<float32>();
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    shatter_lvl2_event.read(buffer);
    target_type_bitfield = buffer.read_pod<int32>();
    disruption_angle_override = buffer.read_pod<float32>();
    disable_event.read(buffer);
    shatter_lvl1_event.read(buffer);
}

