void ADFTypes::StuntArea::read(IO::File& buffer) {
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    name_hash = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        part_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    part_hash = buffer.read_pod<uint32>();
    part_index = buffer.read_pod<uint32>();
    for(int i = 0; i < 16; ++i) {
        deform_points[i] = buffer.read_pod<uint32>();
    }
    for(int i = 0; i < 16; ++i) {
        edge_validity[i] = buffer.read_pod<uint8>();
    }
    number_of_deform_points = buffer.read_pod<uint16>();
    active = buffer.read_pod<uint16>();
    for(int i = 0; i < 48; ++i) {
        vertices3D_local[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 42; ++i) {
        triangle_indices[i] = buffer.read_pod<uint8>();
    }
    number_of_triangles = buffer.read_pod<uint16>();
    bounding_box_local.read(buffer);
    for(int i = 0; i < 3; ++i) {
        center_local[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
}

void ADFTypes::StuntArea::print(std::ostream &out) const {
    out << "name: " << name << "\n";
    out << "name_hash: " << name_hash << "\n";
    out << "part_name: " << part_name << "\n";
    out << "part_hash: " << part_hash << "\n";
    out << "part_index: " << part_index << "\n";
    out << "deform_points: \n";
    deform_points.print(out);
    out << "\n";
    out << "edge_validity: \n";
    edge_validity.print(out);
    out << "\n";
    out << "number_of_deform_points: " << number_of_deform_points << "\n";
    out << "active: " << active << "\n";
    out << "vertices3D_local: \n";
    vertices3D_local.print(out);
    out << "\n";
    out << "triangle_indices: \n";
    triangle_indices.print(out);
    out << "\n";
    out << "number_of_triangles: " << number_of_triangles << "\n";
    bounding_box_local.print(out);
    out << "center_local: \n";
    center_local.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::StuntArea::to_json() const {
    nlohmann::json _res;
    _res["name"] = name;
    _res["name_hash"] = name_hash;
    _res["part_name"] = part_name;
    _res["part_hash"] = part_hash;
    _res["part_index"] = part_index;
    _res["deform_points"] = deform_points.to_json();
    _res["edge_validity"] = edge_validity.to_json();
    _res["number_of_deform_points"] = number_of_deform_points;
    _res["active"] = active;
    _res["vertices3D_local"] = vertices3D_local.to_json();
    _res["triangle_indices"] = triangle_indices.to_json();
    _res["number_of_triangles"] = number_of_triangles;
    _res["bounding_box_local"] = bounding_box_local.to_json();
    _res["center_local"] = center_local.to_json();
    return _res;
}

