void ADFTypes::RespawnPoint::read(IO::File& buffer) {
    EnableEvent.read(buffer);
    DisableEvent.read(buffer);
    MuteEvent.read(buffer);
    UnmuteEvent.read(buffer);
    ActivateEvent.read(buffer);
    OnActivatedEvent.read(buffer);
    ID = buffer.read_pod<uint64>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    NameHash = buffer.read_pod<uint32>();
    for(int i = 0; i < 12; ++i) {
        Transform[i] = buffer.read_pod<float32>();
    }
    Enabled = buffer.read_pod<uint8>();
    IsDefaultPoint = buffer.read_pod<uint8>();
    buffer.skip(2);
    MapIconId = buffer.read_pod<uint64>();
    RespawnPointSlots.read(buffer);
    RespawnPointMissionRequirements.read(buffer);
}

void ADFTypes::RespawnPoint::print(std::ostream &out) const {
    out << "EnableEvent: \n";
    EnableEvent.print(out);
    out << "\n";
    out << "DisableEvent: \n";
    DisableEvent.print(out);
    out << "\n";
    out << "MuteEvent: \n";
    MuteEvent.print(out);
    out << "\n";
    out << "UnmuteEvent: \n";
    UnmuteEvent.print(out);
    out << "\n";
    out << "ActivateEvent: \n";
    ActivateEvent.print(out);
    out << "\n";
    out << "OnActivatedEvent: \n";
    OnActivatedEvent.print(out);
    out << "\n";
    out << "ID: " << ID << "\n";
    out << "Name: " << Name << "\n";
    out << "NameHash: " << NameHash << "\n";
    out << "Transform: \n";
    Transform.print(out);
    out << "\n";
    out << "Enabled: " << Enabled << "\n";
    out << "IsDefaultPoint: " << IsDefaultPoint << "\n";
    out << "MapIconId: " << MapIconId << "\n";
    out << "RespawnPointSlots: \n";
    RespawnPointSlots.print(out);
    out << "\n";
    out << "RespawnPointMissionRequirements: \n";
    RespawnPointMissionRequirements.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::RespawnPoint::to_json() const {
    nlohmann::json _res;
    _res["EnableEvent"] = EnableEvent.to_json();
    _res["DisableEvent"] = DisableEvent.to_json();
    _res["MuteEvent"] = MuteEvent.to_json();
    _res["UnmuteEvent"] = UnmuteEvent.to_json();
    _res["ActivateEvent"] = ActivateEvent.to_json();
    _res["OnActivatedEvent"] = OnActivatedEvent.to_json();
    _res["ID"] = ID;
    _res["Name"] = Name;
    _res["NameHash"] = NameHash;
    _res["Transform"] = Transform.to_json();
    _res["Enabled"] = Enabled;
    _res["IsDefaultPoint"] = IsDefaultPoint;
    _res["MapIconId"] = MapIconId;
    _res["RespawnPointSlots"] = RespawnPointSlots.to_json();
    _res["RespawnPointMissionRequirements"] = RespawnPointMissionRequirements.to_json();
    return _res;
}

