void ADFTypes::CDeployableItemData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    for(int i = 0; i < 4; ++i) {
        color_valid_position[i] = buffer.read_pod<float32>();
    }
    check_path_is_obstructed = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    exclusion_script_tags.read(buffer);
    min_angle_difference = buffer.read_pod<float32>();
    buffer.skip(4);
    outline_ref.read(buffer);
    max_hit_distance_to_floor = buffer.read_pod<float32>();
    check_floor = buffer.read_pod<uint8>();
    buffer.skip(3);
    inclusion_script_tags.read(buffer);
    detection_radius = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        color_invalid_position[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    box_volume_ref.read(buffer);
}

