void ADFTypes::CFocusBeatTargetData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    exit_speed_bump_ease_in = buffer.read_pod<float32>();
    buffer.skip(4);
    activate.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    target_alias.read(buffer);
    deactivate.read(buffer);
    slow_motion_ease_in = buffer.read_pod<float32>();
    target_alias_bone_name = buffer.read_pod<uint32>();
    exit_speed_bump_game_speed = buffer.read_pod<float32>();
    exit_speed_bump_ease_out = buffer.read_pod<float32>();
    slow_motion_game_speed = buffer.read_pod<float32>();
    exit_speed_bump_duration = buffer.read_pod<float32>();
}

void ADFTypes::CFocusBeatTargetData::print(std::ostream &out) const {
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "exit_speed_bump_ease_in: " << exit_speed_bump_ease_in << "\n";
    activate.print(out);
    out << "name: " << name << "\n";
    target_alias.print(out);
    deactivate.print(out);
    out << "slow_motion_ease_in: " << slow_motion_ease_in << "\n";
    out << "target_alias_bone_name: " << target_alias_bone_name << "\n";
    out << "exit_speed_bump_game_speed: " << exit_speed_bump_game_speed << "\n";
    out << "exit_speed_bump_ease_out: " << exit_speed_bump_ease_out << "\n";
    out << "slow_motion_game_speed: " << slow_motion_game_speed << "\n";
    out << "exit_speed_bump_duration: " << exit_speed_bump_duration << "\n";
}

nlohmann::json ADFTypes::CFocusBeatTargetData::to_json() const {
    nlohmann::json _res;
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["exit_speed_bump_ease_in"] = exit_speed_bump_ease_in;
    _res["activate"] = activate.to_json();
    _res["name"] = name;
    _res["target_alias"] = target_alias.to_json();
    _res["deactivate"] = deactivate.to_json();
    _res["slow_motion_ease_in"] = slow_motion_ease_in;
    _res["target_alias_bone_name"] = target_alias_bone_name;
    _res["exit_speed_bump_game_speed"] = exit_speed_bump_game_speed;
    _res["exit_speed_bump_ease_out"] = exit_speed_bump_ease_out;
    _res["slow_motion_game_speed"] = slow_motion_game_speed;
    _res["exit_speed_bump_duration"] = exit_speed_bump_duration;
    return _res;
}

