void ADFTypes::CMissionScoreGiverData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    SMissionRequirementRulesArray.read(buffer);
    show_in_mission_summary = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    reward_package = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        origin_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    icon_type = buffer.read_pod<int32>();
    score_value = buffer.read_pod<int32>();
    penalty = buffer.read_pod<uint8>();
    buffer.skip(3);
    contribution_multiplier = buffer.read_pod<float32>();
    replicate = buffer.read_pod<uint8>();
    buffer.skip(7);
    trigger_event.read(buffer);
    origin_type = buffer.read_pod<int32>();
    buffer.skip(4);
}

