    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "SMissionRequirementRulesArray: \n";
    SMissionRequirementRulesArray.print(out);
    out << "\n";
    out << "show_in_mission_summary: " << show_in_mission_summary << "\n";
    out << "name: " << name << "\n";
    out << "reward_package: " << reward_package << "\n";
    out << "origin_id: " << origin_id << "\n";
    out << "icon_type: " << icon_type << "\n";
    out << "score_value: " << score_value << "\n";
    out << "penalty: " << penalty << "\n";
    out << "contribution_multiplier: " << contribution_multiplier << "\n";
    out << "replicate: " << replicate << "\n";
    trigger_event.print(out);
    out << "origin_type: " << origin_type << "\n";
