    _res["war_effort_pool"] = war_effort_pool;
    _res["contract_x"] = contract_x;
    _res["mission_score_giver_ref"] = mission_score_giver_ref.to_json();
    _res["mission_requirement"] = mission_requirement;
    _res["shared_progress"] = shared_progress;
    _res["depended_on_contracts"] = depended_on_contracts;
    _res["unlock_date_and_time"] = unlock_date_and_time;
    return _res;
