    SAfflictionDamageArray.read(buffer);
    stagger_max = buffer.read_pod<float32>();
    buffer.skip(4);
    small_force_pulse_ref.read(buffer);
    damage_type = buffer.read_pod<int32>();
    tumble_explosion_buff_name = buffer.read_pod<uint32>();
