    tumble_per_object = buffer.read_pod<float32>();
    big_force_pulse_ref.read(buffer);
    big_detonation_threshold = buffer.read_pod<int32>();
    gib_factor_per_object = buffer.read_pod<float32>();
    damage_per_object = buffer.read_pod<float32>();
    buffer.skip(4);
    medium_force_pulse_ref.read(buffer);
    impulse_fizzle = buffer.read_pod<float32>();
    shatter_fizzle = buffer.read_pod<float32>();
    medium_clone_factory_ref.read(buffer);
    shatter_max = buffer.read_pod<float32>();
    buffer.skip(4);
    on_target_is_not_damageable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    small_clone_factory_ref.read(buffer);
    tumble_max = buffer.read_pod<float32>();
    tumble_up_per_object = buffer.read_pod<float32>();
    shatter_per_object = buffer.read_pod<float32>();
