void ADFTypes::CCombatantRuleData::read(IO::File& buffer) {
    ParentCCompoundBaseRule = std::move(Deferred::read(buffer));
    SSpawnPointArray.read(buffer);
    SSoundCSendFunctionArray.read(buffer);
    enable_event.read(buffer);
    start_active = buffer.read_pod<uint8>();
    spawn_count_per_node = buffer.read_pod<uint8>();
    buffer.skip(2);
    spawn_delay_group_size = buffer.read_pod<int32>();
    persist_death = buffer.read_pod<uint8>();
    buffer.skip(3);
    activation_chance = buffer.read_pod<float32>();
    on_hit_event.read(buffer);
    make_invulnerable_event.read(buffer);
    on_despawn_event.read(buffer);
    on_world_at_war_death_event.read(buffer);
    restore_health_event.read(buffer);
    drop_to_one_hp_event.read(buffer);
    invulnerable = buffer.read_pod<uint8>();
    unload_auto_despawn = buffer.read_pod<uint8>();
    buffer.skip(6);
    force_death_event.read(buffer);
    finished_event.read(buffer);
    during_mission = buffer.read_pod<uint8>();
    buffer.skip(7);
    spawn_point_source.read(buffer);
    started_event.read(buffer);
    disable_event.read(buffer);
    initial_interest = buffer.read_pod<int32>();
    spawn_selection = buffer.read_pod<int32>();
    initial_delay = buffer.read_pod<float32>();
    buffer.skip(4);
    enable_invulnerable_to_other_ai.read(buffer);
    on_death_event.read(buffer);
    on_spawn_event.read(buffer);
    block_check = buffer.read_pod<uint8>();
    los_check = buffer.read_pod<uint8>();
    buffer.skip(6);
    change_character_faction_event.read(buffer);
    spawn_delay = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        mission_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    deactivate_event.read(buffer);
    despawn_event.read(buffer);
    spawn_count = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    mission_critical = buffer.read_pod<uint8>();
    spawn_once_only = buffer.read_pod<uint8>();
    buffer.skip(6);
    disable_invulnerable_to_other_ai.read(buffer);
    invulnerable_to_other_ai = buffer.read_pod<uint8>();
    proximity_check = buffer.read_pod<uint8>();
    buffer.skip(6);
    override_target.read(buffer);
    activate_event.read(buffer);
    make_vulnerable_event.read(buffer);
}

