void ADFTypes::ProbabilityBuffer::read(IO::File& buffer) {
    Buffer.read(buffer);
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        AnyValidVariation = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(7);
}

void ADFTypes::ProbabilityBuffer::print(std::ostream &out) const {
    out << "Buffer: \n";
    Buffer.print(out);
    out << "\n";
    out << "AnyValidVariation: " << AnyValidVariation << "\n";
}

