void ADFTypes::CWeaponPlacementRuleData::read(IO::File& buffer) {
    ParentCPlacementRule = std::move(Deferred::read(buffer));
    CLaserBeamWeaponComponent = std::move(Deferred::read(buffer));
    CTurretWeaponComponent = std::move(Deferred::read(buffer));
    CModelAttachementWeaponComponentArray.read(buffer);
    SSpawnWeaponSeat = std::move(Deferred::read(buffer));
    CFOWControllerWeaponComponent = std::move(Deferred::read(buffer));
    CSpotlightWeaponComponent = std::move(Deferred::read(buffer));
    CAirplaneFlybyWeaponComponent = std::move(Deferred::read(buffer));
    InfiniteAmount = buffer.read_pod<uint8>();
    buffer.skip(7);
    MakeTurretFriendly.read(buffer);
    weapon_only_activate_event.read(buffer);
    WeaponRackUseOrdinaryPickup = buffer.read_pod<uint8>();
    buffer.skip(3);
    ExtraAmmoAmount = buffer.read_pod<int32>();
    TurretInitialMissPlayerCount = buffer.read_pod<int32>();
    buffer.skip(4);
    OnPickedUpAmmoEvent.read(buffer);
    character_only_despawn_event.read(buffer);
    TurretInitialMissPlayerOffset = buffer.read_pod<float32>();
    buffer.skip(4);
    MakeTurretHostile.read(buffer);
    Invisible = buffer.read_pod<uint8>();
    persist_death = buffer.read_pod<uint8>();
    military_outpost_spawn = buffer.read_pod<uint8>();
    buffer.skip(5);
    weapon_only_despawn_event.read(buffer);
    OnPickedUpEvent.read(buffer);
    OnMountedWeaponMounted.read(buffer);
    OnTurretIsFriendly.read(buffer);
    WeaponRack = buffer.read_pod<uint8>();
    RebelDrop = buffer.read_pod<uint8>();
    buffer.skip(6);
    character_only_activate_event.read(buffer);
}

