    mud_dry = buffer.read_pod<uint8>();
    cardboard = buffer.read_pod<uint8>();
    metal_car = buffer.read_pod<uint8>();
    water = buffer.read_pod<uint8>();
    stone = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    concrete_debris = buffer.read_pod<uint8>();
    metal = buffer.read_pod<uint8>();
    air = buffer.read_pod<uint8>();
    concrete = buffer.read_pod<uint8>();
    sand = buffer.read_pod<uint8>();
    grass = buffer.read_pod<uint8>();
    buffer.skip(2);
