    SSpellActArray.read(buffer);
    SSpellBuffArray.read(buffer);
    SSpellShatterArray.read(buffer);
    SSpellStaggerArray.read(buffer);
    SSpellGibArray.read(buffer);
    SSpellDamageArray.read(buffer);
