void ADFTypes::CIntentTriggerData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    event_finished_playing.read(buffer);
    specific_character_to_process_intent_ref.read(buffer);
    intent_radius = buffer.read_pod<float32>();
    buffer.skip(4);
    event_failed_playing.read(buffer);
    specific_receiver_to_process_intent_alias.read(buffer);
    broadcast_from_object = buffer.read_pod<uint8>();
    buffer.skip(3);
    _exportable = buffer.read_pod<int32>();
    intent_position = buffer.read_pod<int32>();
    buffer.skip(4);
    event_trigger.read(buffer);
    intent_radius_increment = buffer.read_pod<float32>();
    buffer.skip(4);
    event_enable.read(buffer);
    event_started_playing.read(buffer);
    broadcast_frame_life = buffer.read_pod<float32>();
    intent_name = buffer.read_pod<uint32>();
    trigger_on_enabled = buffer.read_pod<uint8>();
    buffer.skip(7);
    specific_receiver_to_process_intent_ref.read(buffer);
    intent_lifetime = buffer.read_pod<float32>();
    buffer.skip(4);
    specific_character_to_process_intent_alias.read(buffer);
    unique_character_to_process_intent = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_disable.read(buffer);
    enabled = buffer.read_pod<uint8>();
    buffer.skip(7);
}

