void ADFTypes::CNpcSupportItemMountedWeaponData::read(IO::File& buffer) {
    ParentCNpcSupportItem = std::move(Deferred::read(buffer));
    horizontal_angle_min = buffer.read_pod<float32>();
    buffer.skip(4);
    RigidObject.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_over_heated.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        key_weapon_is_firing = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    max_fire_time = buffer.read_pod<float32>();
    horizontal_angle_max = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        key_weapon_aim_position = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    GunObject.read(buffer);
    vertical_angle_max = buffer.read_pod<float32>();
    buffer.skip(4);
    on_cooled_off.read(buffer);
    for(int i = 0; i < 16; ++i) {
        offset[i] = buffer.read_pod<float32>();
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        key_weapon_heat = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    wind_up_before_firing = buffer.read_pod<float32>();
    cool_down_time = buffer.read_pod<float32>();
    vertical_angle_min = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        key_is_over_heated = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        bone_attachment = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

