void ADFTypes::CDamageableHealthRegainpoolData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    regainpool_max_difficulty_amount_regained = buffer.read_pod<float32>();
    buffer.skip(4);
    on_start_recharge_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    force_recharge_event.read(buffer);
    regainpool_regen_rate = buffer.read_pod<float32>();
    buffer.skip(4);
    on_critical_health_threshold_event.read(buffer);
    on_hit_event.read(buffer);
    critical_health_threshold = buffer.read_pod<int32>();
    regen_to_critical_health_threshold = buffer.read_pod<uint8>();
    buffer.skip(3);
    on_recharge_done_event.read(buffer);
    regainpool_min_difficulty_amount_regained = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        regainpool_recharge_effect_usage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    regainpool_regen_cooldown = buffer.read_pod<float32>();
    buffer.skip(4);
}

