void ADFTypes::CDebugTextObjectData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    SDebugTextComponentArray.read(buffer);
    enable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    message_lines = buffer.read_pod<int32>();
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    message_lifespan = buffer.read_pod<float32>();
    buffer.skip(4);
    clear_event.read(buffer);
    event_0.read(buffer);
    is_3d = buffer.read_pod<uint8>();
    buffer.skip(3);
    message_fontsize = buffer.read_pod<float32>();
    _auto_show_0 = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        message_color[i] = buffer.read_pod<float32>();
    }
    allow_visible_in_final = buffer.read_pod<uint8>();
    buffer.skip(7);
    disable_event.read(buffer);
    for(int i = 0; i < 2; ++i) {
        message_pos[i] = buffer.read_pod<float32>();
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        text_0 = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::CDebugTextObjectData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "SDebugTextComponentArray: \n";
    SDebugTextComponentArray.print(out);
    out << "\n";
    enable_event.print(out);
    out << "name: " << name << "\n";
    out << "message_lines: " << message_lines << "\n";
    out << "enabled: " << enabled << "\n";
    out << "message_lifespan: " << message_lifespan << "\n";
    clear_event.print(out);
    event_0.print(out);
    out << "is_3d: " << is_3d << "\n";
    out << "message_fontsize: " << message_fontsize << "\n";
    out << "_auto_show_0: " << _auto_show_0 << "\n";
    out << "message_color: \n";
    message_color.print(out);
    out << "\n";
    out << "allow_visible_in_final: " << allow_visible_in_final << "\n";
    disable_event.print(out);
    out << "message_pos: \n";
    message_pos.print(out);
    out << "\n";
    out << "text_0: " << text_0 << "\n";
}

nlohmann::json ADFTypes::CDebugTextObjectData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    _res["SDebugTextComponentArray"] = SDebugTextComponentArray.to_json();
    _res["enable_event"] = enable_event.to_json();
    _res["name"] = name;
    _res["message_lines"] = message_lines;
    _res["enabled"] = enabled;
    _res["message_lifespan"] = message_lifespan;
    _res["clear_event"] = clear_event.to_json();
    _res["event_0"] = event_0.to_json();
    _res["is_3d"] = is_3d;
    _res["message_fontsize"] = message_fontsize;
    _res["_auto_show_0"] = _auto_show_0;
    _res["message_color"] = message_color.to_json();
    _res["allow_visible_in_final"] = allow_visible_in_final;
    _res["disable_event"] = disable_event.to_json();
    _res["message_pos"] = message_pos.to_json();
    _res["text_0"] = text_0;
    return _res;
}

