void ADFTypes::CEventTriggerData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    SEventTriggerComponentArray.read(buffer);
    relay_event.read(buffer);
    reset_event.read(buffer);
    enable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    random_event.read(buffer);
    show_debugging_info = buffer.read_pod<uint8>();
    buffer.skip(7);
    prev_event.read(buffer);
    saved = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        text = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    next_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        backend_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    disable_event.read(buffer);
    pass_text = buffer.read_pod<uint8>();
    enabled = buffer.read_pod<uint8>();
    randomize_unique_indices = buffer.read_pod<uint8>();
    buffer.skip(5);
}

void ADFTypes::CEventTriggerData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "SEventTriggerComponentArray: \n";
    SEventTriggerComponentArray.print(out);
    out << "\n";
    relay_event.print(out);
    reset_event.print(out);
    enable_event.print(out);
    out << "name: " << name << "\n";
    random_event.print(out);
    out << "show_debugging_info: " << show_debugging_info << "\n";
    prev_event.print(out);
    out << "saved: " << saved << "\n";
    out << "text: " << text << "\n";
    next_event.print(out);
    out << "backend_id: " << backend_id << "\n";
    disable_event.print(out);
    out << "pass_text: " << pass_text << "\n";
    out << "enabled: " << enabled << "\n";
    out << "randomize_unique_indices: " << randomize_unique_indices << "\n";
}

nlohmann::json ADFTypes::CEventTriggerData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["SEventTriggerComponentArray"] = SEventTriggerComponentArray.to_json();
    _res["relay_event"] = relay_event.to_json();
    _res["reset_event"] = reset_event.to_json();
    _res["enable_event"] = enable_event.to_json();
    _res["name"] = name;
    _res["random_event"] = random_event.to_json();
    _res["show_debugging_info"] = show_debugging_info;
    _res["prev_event"] = prev_event.to_json();
    _res["saved"] = saved;
    _res["text"] = text;
    _res["next_event"] = next_event.to_json();
    _res["backend_id"] = backend_id;
    _res["disable_event"] = disable_event.to_json();
    _res["pass_text"] = pass_text;
    _res["enabled"] = enabled;
    _res["randomize_unique_indices"] = randomize_unique_indices;
    return _res;
}

