void ADFTypes::CElectricalArcData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    point_light_intensity = buffer.read_pod<float32>();
    buffer.skip(4);
    impact_clone_factory_ref.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        normal_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        diffuse_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    point_light_ref.read(buffer);
    arc_damage_radius = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        properties_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ignore_players = buffer.read_pod<uint8>();
    buffer.skip(3);
    tuning_file = buffer.read_pod<int32>();
}

void ADFTypes::CElectricalArcData::print(std::ostream &out) const {
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "point_light_intensity: " << point_light_intensity << "\n";
    impact_clone_factory_ref.print(out);
    out << "normal_texture: " << normal_texture << "\n";
    out << "name: " << name << "\n";
    out << "diffuse_texture: " << diffuse_texture << "\n";
    point_light_ref.print(out);
    out << "arc_damage_radius: " << arc_damage_radius << "\n";
    out << "properties_texture: " << properties_texture << "\n";
    out << "ignore_players: " << ignore_players << "\n";
    out << "tuning_file: " << tuning_file << "\n";
}

nlohmann::json ADFTypes::CElectricalArcData::to_json() const {
    nlohmann::json _res;
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["point_light_intensity"] = point_light_intensity;
    _res["impact_clone_factory_ref"] = impact_clone_factory_ref.to_json();
    _res["normal_texture"] = normal_texture;
    _res["name"] = name;
    _res["diffuse_texture"] = diffuse_texture;
    _res["point_light_ref"] = point_light_ref.to_json();
    _res["arc_damage_radius"] = arc_damage_radius;
    _res["properties_texture"] = properties_texture;
    _res["ignore_players"] = ignore_players;
    _res["tuning_file"] = tuning_file;
    return _res;
}

