void ADFTypes::CParameterModulatorData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    enable_event.read(buffer);
    envelope_start_event.read(buffer);
    multiply_with_distance_to_listener = buffer.read_pod<uint8>();
    buffer.skip(7);
    on_envelope_expired.read(buffer);
    envelope_value1 = buffer.read_pod<float32>();
    buffer.skip(4);
    envelope_stop_event.read(buffer);
    variable_update_event.read(buffer);
    inverted_normalize_distance = buffer.read_pod<uint8>();
    buffer.skip(7);
    automation_start_event.read(buffer);
    random_max = buffer.read_pod<float32>();
    buffer.skip(4);
    disable_event.read(buffer);
    disable_outside_max_distance = buffer.read_pod<uint8>();
    use_random_multiplier = buffer.read_pod<uint8>();
    buffer.skip(6);
    automation_stop_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        sound_module_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    gain = buffer.read_pod<float32>();
    random_min = buffer.read_pod<float32>();
    object_reference.read(buffer);
    max_distance = buffer.read_pod<float32>();
    envelope_value0 = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        sound_module_query_function_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<uint8>();
    normalize_distance = buffer.read_pod<uint8>();
    buffer.skip(6);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        object_alias = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        sound_module_query_arg = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    envelope_slope_type = buffer.read_pod<int32>();
    envelope_width = buffer.read_pod<float32>();
}

