void ADFTypes::CHeadgearLaserData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 4; ++i) {
        color[i] = buffer.read_pod<float32>();
    }
    width = buffer.read_pod<float32>();
    do_collision_each_frame = buffer.read_pod<uint8>();
    buffer.skip(3);
    emissiveness = buffer.read_pod<float32>();
    buffer.skip(4);
}

void ADFTypes::CHeadgearLaserData::print(std::ostream &out) const {
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "name: " << name << "\n";
    out << "color: \n";
    color.print(out);
    out << "\n";
    out << "width: " << width << "\n";
    out << "do_collision_each_frame: " << do_collision_each_frame << "\n";
    out << "emissiveness: " << emissiveness << "\n";
}

nlohmann::json ADFTypes::CHeadgearLaserData::to_json() const {
    nlohmann::json _res;
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["name"] = name;
    _res["color"] = color.to_json();
    _res["width"] = width;
    _res["do_collision_each_frame"] = do_collision_each_frame;
    _res["emissiveness"] = emissiveness;
    return _res;
}

static std::unique_ptr<ADFTypes::CHeadgearLaserData> CHeadgearLaserData_new_instance() {
    return std::make_unique<ADFTypes::CHeadgearLaserData>();
}

