void ADFTypes::SHordeModeSpawnQueueData::read(IO::File& buffer) {
    starting_budget = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    additional_active_dinos_limit_per_increment = buffer.read_pod<int32>();
    buffer.skip(4);
    spawn_event.read(buffer);
    starting_active_dinos_limit = buffer.read_pod<int32>();
    budget_increment_number_of_waves = buffer.read_pod<int32>();
    budget_hard_cap = buffer.read_pod<int32>();
    buffer.skip(4);
    dinos_spawn_tags.read(buffer);
    active_dinos_limit_hard_cap = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        queue_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    additional_budget_per_increment = buffer.read_pod<int32>();
    active_dinos_limit_increment_number_of_waves = buffer.read_pod<int32>();
}

void ADFTypes::SHordeModeSpawnQueueData::print(std::ostream &out) const {
    out << "starting_budget: " << starting_budget << "\n";
    out << "name: " << name << "\n";
    out << "additional_active_dinos_limit_per_increment: " << additional_active_dinos_limit_per_increment << "\n";
    spawn_event.print(out);
    out << "starting_active_dinos_limit: " << starting_active_dinos_limit << "\n";
    out << "budget_increment_number_of_waves: " << budget_increment_number_of_waves << "\n";
    out << "budget_hard_cap: " << budget_hard_cap << "\n";
    out << "dinos_spawn_tags: \n";
    dinos_spawn_tags.print(out);
    out << "\n";
    out << "active_dinos_limit_hard_cap: " << active_dinos_limit_hard_cap << "\n";
    out << "queue_id: " << queue_id << "\n";
    out << "additional_budget_per_increment: " << additional_budget_per_increment << "\n";
    out << "active_dinos_limit_increment_number_of_waves: " << active_dinos_limit_increment_number_of_waves << "\n";
}

