void ADFTypes::CCalloutTypeData::read(IO::File& buffer) {
    ParentCCalloutBase = std::move(Deferred::read(buffer));
    contextual_fallback = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        animation_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    attaches_to_objective = buffer.read_pod<uint8>();
    attaches_to_acting_player = buffer.read_pod<uint8>();
    buffer.skip(2);
    callout_group_type = buffer.read_pod<int32>();
    attaches_to_entity = buffer.read_pod<uint8>();
    buffer.skip(3);
    lifetime = buffer.read_pod<float32>();
    display_healthbar = buffer.read_pod<uint8>();
    contextual_callout = buffer.read_pod<uint8>();
    buffer.skip(6);
}

void ADFTypes::CCalloutTypeData::print(std::ostream &out) const {
    out << "ParentCCalloutBase: " << "\n";
    if (ParentCCalloutBase) {
        ParentCCalloutBase->print(out);
    }
    out << "contextual_fallback: " << contextual_fallback << "\n";
    out << "name: " << name << "\n";
    out << "animation_id: " << animation_id << "\n";
    out << "attaches_to_objective: " << attaches_to_objective << "\n";
    out << "attaches_to_acting_player: " << attaches_to_acting_player << "\n";
    out << "callout_group_type: " << callout_group_type << "\n";
    out << "attaches_to_entity: " << attaches_to_entity << "\n";
    out << "lifetime: " << lifetime << "\n";
    out << "display_healthbar: " << display_healthbar << "\n";
    out << "contextual_callout: " << contextual_callout << "\n";
}

nlohmann::json ADFTypes::CCalloutTypeData::to_json() const {
    nlohmann::json _res;
    if (ParentCCalloutBase) {
        _res["ParentCCalloutBase"] = ParentCCalloutBase->to_json();
    }
    _res["contextual_fallback"] = contextual_fallback;
    _res["name"] = name;
    _res["animation_id"] = animation_id;
    _res["attaches_to_objective"] = attaches_to_objective;
    _res["attaches_to_acting_player"] = attaches_to_acting_player;
    _res["callout_group_type"] = callout_group_type;
    _res["attaches_to_entity"] = attaches_to_entity;
    _res["lifetime"] = lifetime;
    _res["display_healthbar"] = display_healthbar;
    _res["contextual_callout"] = contextual_callout;
    return _res;
}

