void ADFTypes::CDynamicLightFlasherData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    priority = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    quadratic_attenuation = buffer.read_pod<float32>();
    multiplier = buffer.read_pod<float32>();
    linear_attenuation = buffer.read_pod<float32>();
    flash_pause = buffer.read_pod<float32>();
    fade_in_duration = buffer.read_pod<float32>();
    receive_matrix_event.read(buffer);
    radius = buffer.read_pod<float32>();
    buffer.skip(4);
    enable_on_event.read(buffer);
    disable_on_event.read(buffer);
    duration = buffer.read_pod<float32>();
    constant_attenuation = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        diffuse[i] = buffer.read_pod<float32>();
    }
    fade_out_duration = buffer.read_pod<float32>();
}

