    _res["shattered_pieces_clone_factory_ref"] = shattered_pieces_clone_factory_ref.to_json();
    _res["local_spawn_vel_max"] = local_spawn_vel_max.to_json();
    _res["disable_event"] = disable_event.to_json();
    _res["on_spawned_event"] = on_spawned_event.to_json();
    _res["player_rel_vel_max"] = player_rel_vel_max.to_json();
    _res["shatter_event"] = shatter_event.to_json();
    _res["player_rel_vel_min"] = player_rel_vel_min.to_json();
    _res["angular_vel_min"] = angular_vel_min.to_json();
    _res["spawn_event"] = spawn_event.to_json();
    _res["clone_factory_ref"] = clone_factory_ref.to_json();
