void ADFTypes::SIKChainTwoBonesData::read(IO::File& buffer) {
    ParentCEditorTransformable = std::move(Deferred::read(buffer));
    SIKNodeLimitsArray.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        end_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        at_vector[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        middle_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        base_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::SIKChainTwoBonesData::print(std::ostream &out) const {
    out << "ParentCEditorTransformable: " << "\n";
    if (ParentCEditorTransformable) {
        ParentCEditorTransformable->print(out);
    }
    out << "SIKNodeLimitsArray: \n";
    SIKNodeLimitsArray.print(out);
    out << "\n";
    out << "name: " << name << "\n";
    out << "end_joint: " << end_joint << "\n";
    out << "at_vector: \n";
    at_vector.print(out);
    out << "\n";
    out << "middle_joint: " << middle_joint << "\n";
    out << "base_joint: " << base_joint << "\n";
}

nlohmann::json ADFTypes::SIKChainTwoBonesData::to_json() const {
    nlohmann::json _res;
    if (ParentCEditorTransformable) {
        _res["ParentCEditorTransformable"] = ParentCEditorTransformable->to_json();
    }
    _res["SIKNodeLimitsArray"] = SIKNodeLimitsArray.to_json();
    _res["name"] = name;
    _res["end_joint"] = end_joint;
    _res["at_vector"] = at_vector.to_json();
    _res["middle_joint"] = middle_joint;
    _res["base_joint"] = base_joint;
    return _res;
}

