void ADFTypes::CInteractionGraphExitData::read(IO::File& buffer) {
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    Parent_CInteractionGraphTraversalEvents = std::move(Deferred::read(buffer));
    CInteractionGraphMoveFractionCondition = std::move(Deferred::read(buffer));
    CInteractionGraphParentVelocityCondition = std::move(Deferred::read(buffer));
    CInteractionGraphParentIsUpRightCondition = std::move(Deferred::read(buffer));
    CInteractionGraphParentHasDriverCondition = std::move(Deferred::read(buffer));
    CInteractionGraphExitObstructedCondition = std::move(Deferred::read(buffer));
    CInteractionGraphUserIsPlayerCondition = std::move(Deferred::read(buffer));
    CInteractionGraphVehiclePartUnlockedConditionArray.read(buffer);
    exit_position_obstruction = buffer.read_pod<uint8>();
    buffer.skip(3);
    ai_act_event = buffer.read_pod<uint32>();
    movement_identifier = buffer.read_pod<int32>();
    exit_position_projection = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        state = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    interaction.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        modifier = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    use_exit_transform = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

