void ADFTypes::SVehicleSafeModeData::read(IO::File& buffer) {
    on_fully_restored_event.read(buffer);
    on_exit_safe_mode_event.read(buffer);
    safe_mode_start_repair_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    blink_use_original_color = buffer.read_pod<uint8>();
    buffer.skip(7);
    on_started_repair_event.read(buffer);
    on_enter_safe_mode_event.read(buffer);
    blink_frequency = buffer.read_pod<float32>();
    buffer.skip(4);
    on_safe_mode_active_idling_event.read(buffer);
    blink_multiplier = buffer.read_pod<float32>();
    buffer.skip(4);
    on_stopped_repair_event.read(buffer);
    safe_mode_stop_repair_event.read(buffer);
    for(int i = 0; i < 3; ++i) {
        blink_color[i] = buffer.read_pod<float32>();
    }
    blink_emissive_scale = buffer.read_pod<float32>();
}

void ADFTypes::SVehicleSafeModeData::print(std::ostream &out) const {
    on_fully_restored_event.print(out);
    on_exit_safe_mode_event.print(out);
    safe_mode_start_repair_event.print(out);
    out << "name: " << name << "\n";
    out << "blink_use_original_color: " << blink_use_original_color << "\n";
    on_started_repair_event.print(out);
    on_enter_safe_mode_event.print(out);
    out << "blink_frequency: " << blink_frequency << "\n";
    on_safe_mode_active_idling_event.print(out);
    out << "blink_multiplier: " << blink_multiplier << "\n";
    on_stopped_repair_event.print(out);
    safe_mode_stop_repair_event.print(out);
    out << "blink_color: \n";
    blink_color.print(out);
    out << "\n";
    out << "blink_emissive_scale: " << blink_emissive_scale << "\n";
}

nlohmann::json ADFTypes::SVehicleSafeModeData::to_json() const {
    nlohmann::json _res;
    _res["on_fully_restored_event"] = on_fully_restored_event.to_json();
    _res["on_exit_safe_mode_event"] = on_exit_safe_mode_event.to_json();
    _res["safe_mode_start_repair_event"] = safe_mode_start_repair_event.to_json();
    _res["name"] = name;
    _res["blink_use_original_color"] = blink_use_original_color;
    _res["on_started_repair_event"] = on_started_repair_event.to_json();
    _res["on_enter_safe_mode_event"] = on_enter_safe_mode_event.to_json();
    _res["blink_frequency"] = blink_frequency;
    _res["on_safe_mode_active_idling_event"] = on_safe_mode_active_idling_event.to_json();
    _res["blink_multiplier"] = blink_multiplier;
    _res["on_stopped_repair_event"] = on_stopped_repair_event.to_json();
    _res["safe_mode_stop_repair_event"] = safe_mode_stop_repair_event.to_json();
    _res["blink_color"] = blink_color.to_json();
    _res["blink_emissive_scale"] = blink_emissive_scale;
    return _res;
}

