void ADFTypes::CEnvironmentLightingObjectData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    sun_intensity_multiplier = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        shadow_cascades_constant_depth_bias[i] = buffer.read_pod<float32>();
    }
    cloud_shadow_intensity_multiplier = buffer.read_pod<float32>();
    shadow_cascades_depth_range = buffer.read_pod<float32>();
    sun_direction_override_enabled = buffer.read_pod<int32>();
    cutscene_light_intensity_override_enabled = buffer.read_pod<int32>();
    cutscene_light_intensity_scale = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        shadow_cascades_radius[i] = buffer.read_pod<float32>();
    }
    cloud_shadow_enabled = buffer.read_pod<int32>();
    sun_position_override_enabled = buffer.read_pod<int32>();
    sun_intensity_override_enabled = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        sun_Direction[i] = buffer.read_pod<float32>();
    }
    shadow_override_enabled = buffer.read_pod<int32>();
    sun_position_bearing = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        shadow_cascades_shadow_depth_bias[i] = buffer.read_pod<float32>();
    }
    sun_position_height = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        shadow_cascades_slope_depth_bias[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

