void ADFTypes::CSimpleMotionData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Interp = buffer.read_pod<int32>();
    TriggerDelayMax = buffer.read_pod<float32>();
    TriggerDelayMin = buffer.read_pod<float32>();
    buffer.skip(4);
    Trigger.read(buffer);
    _exportable = buffer.read_pod<int32>();
    InterpTime = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        Position[i] = buffer.read_pod<float32>();
    }
    OnArrive.read(buffer);
}

void ADFTypes::CSimpleMotionData::print(std::ostream &out) const {
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "name: " << name << "\n";
    out << "Interp: " << Interp << "\n";
    out << "TriggerDelayMax: " << TriggerDelayMax << "\n";
    out << "TriggerDelayMin: " << TriggerDelayMin << "\n";
    Trigger.print(out);
    out << "_exportable: " << _exportable << "\n";
    out << "InterpTime: " << InterpTime << "\n";
    out << "Position: \n";
    Position.print(out);
    out << "\n";
    OnArrive.print(out);
}

nlohmann::json ADFTypes::CSimpleMotionData::to_json() const {
    nlohmann::json _res;
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["name"] = name;
    _res["Interp"] = Interp;
    _res["TriggerDelayMax"] = TriggerDelayMax;
    _res["TriggerDelayMin"] = TriggerDelayMin;
    _res["Trigger"] = Trigger.to_json();
    _res["_exportable"] = _exportable;
    _res["InterpTime"] = InterpTime;
    _res["Position"] = Position.to_json();
    _res["OnArrive"] = OnArrive.to_json();
    return _res;
}

