void ADFTypes::Event::read(IO::File& buffer) {
    NameHash = buffer.read_pod<uint32>();
    buffer.skip(4);
    GlobalEventHash = buffer.read_pod<uint64>();
    DialoguePresetIndex = buffer.read_pod<uint32>();
    buffer.skip(4);
    Variations.read(buffer);
    VariationIndex = buffer.read_pod<uint32>();
    Replicate = buffer.read_pod<uint8>();
    buffer.skip(3);
}

