void ADFTypes::CObjectiveData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    suppress_completed_notification = buffer.read_pod<uint8>();
    has_cleanup_state = buffer.read_pod<uint8>();
    buffer.skip(6);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    icon_type = buffer.read_pod<int32>();
    debug_objective_restartpoint = buffer.read_pod<uint32>();
    on_completed_gui_pause_delay = buffer.read_pod<float32>();
    has_init_state = buffer.read_pod<uint8>();
    main_mission_objective = buffer.read_pod<uint8>();
    buffer.skip(2);
    objective_list_order = buffer.read_pod<int32>();
    force_track_objective = buffer.read_pod<uint8>();
    show_on_insertion_map = buffer.read_pod<uint8>();
    buffer.skip(2);
    log_objective_desc = buffer.read_pod<uint32>();
    show_on_mission_HUD = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        objective_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    show_activated_notification = buffer.read_pod<uint8>();
    standalone_objective = buffer.read_pod<uint8>();
    buffer.skip(2);
    log_objective_name = buffer.read_pod<uint32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        sound_module_receiving_status = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

