void ADFTypes::AmfStreamAttribute::read(IO::File& buffer) {
    Usage = static_cast<ADFTypes::AmfUsage>(buffer.read_pod<uint32>());
    Format = static_cast<ADFTypes::AmfFormat>(buffer.read_pod<uint32>());
    StreamIndex = buffer.read_pod<uint8>();
    StreamOffset = buffer.read_pod<uint8>();
    StreamStride = buffer.read_pod<uint8>();
    for(int i = 0; i < 8; ++i) {
        PackingData[i] = buffer.read_pod<uint8>();
    }
    buffer.skip(1);
}

void ADFTypes::AmfStreamAttribute::print(std::ostream &out) const {
    out << "Usage: " << Usage << "\n";
    out << "Format: " << Format << "\n";
    out << "StreamIndex: " << StreamIndex << "\n";
    out << "StreamOffset: " << StreamOffset << "\n";
    out << "StreamStride: " << StreamStride << "\n";
    out << "PackingData: \n";
    PackingData.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::AmfStreamAttribute::to_json() const {
    nlohmann::json _res;
    _res["Usage"] = Usage;
    _res["Format"] = Format;
    _res["StreamIndex"] = StreamIndex;
    _res["StreamOffset"] = StreamOffset;
    _res["StreamStride"] = StreamStride;
    _res["PackingData"] = PackingData.to_json();
    return _res;
}

