void ADFTypes::CDeployableTurretControlData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    orbit_hover_range = buffer.read_pod<float32>();
    orbit_point_height = buffer.read_pod<float32>();
    orbit_initial_impulse_force = buffer.read_pod<float32>();
    orbit_hover_speed = buffer.read_pod<float32>();
    orbit_pull_velocity_limit = buffer.read_pod<float32>();
    buffer.skip(4);
    start_brake.read(buffer);
    orbit_close_velocity_limit = buffer.read_pod<float32>();
    orbit_recenter_dist = buffer.read_pod<float32>();
    self_damage_per_second = buffer.read_pod<int32>();
    settle_time = buffer.read_pod<float32>();
    orbit_pull_force = buffer.read_pod<float32>();
    buffer.skip(4);
    weapon_ref.read(buffer);
    orbit_base_radius = buffer.read_pod<float32>();
    orbit_pull_dampening = buffer.read_pod<float32>();
    near_distance_xz_from_player = buffer.read_pod<float32>();
    should_hover = buffer.read_pod<uint8>();
    buffer.skip(3);
    orbit_return_drag = buffer.read_pod<float32>();
    tilting_self_damage_initial_wait_time = buffer.read_pod<float32>();
    on_settle.read(buffer);
    orbit_max_radius = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    should_apply_recoil = buffer.read_pod<uint8>();
    buffer.skip(3);
    max_time_before_settle = buffer.read_pod<float32>();
    recoil_force = buffer.read_pod<float32>();
    orbit_close_dampening = buffer.read_pod<float32>();
    take_damage_if_tilted = buffer.read_pod<uint8>();
    buffer.skip(3);
    tilting_self_damage_per_second = buffer.read_pod<int32>();
    orbit_point_ref.read(buffer);
}

