void ADFTypes::CHordeModeHandlerData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    SHordeModeSpawnQueueArray.read(buffer);
    shock_turret_ammo_purchase_cost = buffer.read_pod<int32>();
    budget_refund_delay = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ammo_refill_cost = buffer.read_pod<int32>();
    buffer.skip(4);
    shock_turret_ammo_purchased_event.read(buffer);
    equipment_refill_cost = buffer.read_pod<int32>();
    buffer.skip(4);
    default_turret_ammo_purchased_event.read(buffer);
    explosive_turret_ammo_purchase_cost = buffer.read_pod<int32>();
    total_active_dinos_limit_hard_cap = buffer.read_pod<int32>();
    default_turret_ammo_purchase_cost = buffer.read_pod<int32>();
    buffer.skip(4);
    explosive_turret_ammo_purchased_event.read(buffer);
    wave_completed_event.read(buffer);
    personal_points_awarded_on_wave_completion = buffer.read_pod<int32>();
    buffer.skip(4);
}

