void ADFTypes::TerrainOccluderMesh::read(IO::File& buffer) {
    for(int i = 0; i < 6; ++i) {
        BoundingBox[i] = buffer.read_pod<float32>();
    }
    Vertices.read(buffer);
    Indices.read(buffer);
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        TriangleOmitted = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(4);
}

void ADFTypes::TerrainOccluderMesh::print(std::ostream &out) const {
    out << "BoundingBox: \n";
    BoundingBox.print(out);
    out << "\n";
    out << "Vertices: \n";
    Vertices.print(out);
    out << "\n";
    out << "Indices: \n";
    Indices.print(out);
    out << "\n";
    out << "TriangleOmitted: " << TriangleOmitted << "\n";
}

nlohmann::json ADFTypes::TerrainOccluderMesh::to_json() const {
    nlohmann::json _res;
    _res["BoundingBox"] = BoundingBox.to_json();
    _res["Vertices"] = Vertices.to_json();
    _res["Indices"] = Indices.to_json();
    _res["TriangleOmitted"] = TriangleOmitted;
    return _res;
}

