void ADFTypes::RestartPoint::read(IO::File& buffer) {
    OnLoadEvent.read(buffer);
    GlobalEnableEvent.read(buffer);
    GlobalDisableEvent.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ID = buffer.read_pod<uint64>();
    NameId = buffer.read_pod<uint32>();
    for(int i = 0; i < 12; ++i) {
        Transform[i] = buffer.read_pod<float32>();
    }
    Type = buffer.read_pod<uint8>();
    Enabled = buffer.read_pod<uint8>();
    PlayerPlacement = buffer.read_pod<uint8>();
    buffer.skip(1);
    LocationHash = buffer.read_pod<uint32>();
    buffer.skip(4);
}

