void ADFTypes::SUILocValueData::read(IO::File& buffer) {
    order_id = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    value = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        description = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::SUILocValueData::print(std::ostream &out) const {
    out << "order_id: " << order_id << "\n";
    out << "name: " << name << "\n";
    out << "value: " << value << "\n";
    out << "description: " << description << "\n";
}

nlohmann::json ADFTypes::SUILocValueData::to_json() const {
    nlohmann::json _res;
    _res["order_id"] = order_id;
    _res["name"] = name;
    _res["value"] = value;
    _res["description"] = description;
    return _res;
}

