void ADFTypes::ADF_HashTable_uint32_int32_1::read(IO::File& buffer) {
    HashTable = buffer.read_pod<u64>();
    ChainPool = buffer.read_pod<u64>();
    HashTableLength = buffer.read_pod<uint16>();
    FirstFreeChain = buffer.read_pod<uint16>();
    ChainPoolSize = buffer.read_pod<uint16>();
    ChainPoolFreeCount = buffer.read_pod<uint16>();
    Size = buffer.read_pod<uint16>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        UserAllocated = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        Dirty = (bitfield_value >> 1) & ((1ULL << 1) - 1);
    }
    buffer.skip(4);
}

void ADFTypes::ADF_HashTable_uint32_int32_1::print(std::ostream &out) const {
    out << "HashTable: " << HashTable << "\n";
    out << "ChainPool: " << ChainPool << "\n";
    out << "HashTableLength: " << HashTableLength << "\n";
    out << "FirstFreeChain: " << FirstFreeChain << "\n";
    out << "ChainPoolSize: " << ChainPoolSize << "\n";
    out << "ChainPoolFreeCount: " << ChainPoolFreeCount << "\n";
    out << "Size: " << Size << "\n";
    out << "UserAllocated: " << UserAllocated << "\n";
    out << "Dirty: " << Dirty << "\n";
}

nlohmann::json ADFTypes::ADF_HashTable_uint32_int32_1::to_json() const {
    nlohmann::json _res;
    _res["HashTable"] = HashTable;
    _res["ChainPool"] = ChainPool;
    _res["HashTableLength"] = HashTableLength;
    _res["FirstFreeChain"] = FirstFreeChain;
    _res["ChainPoolSize"] = ChainPoolSize;
    _res["ChainPoolFreeCount"] = ChainPoolFreeCount;
    _res["Size"] = Size;
    _res["UserAllocated"] = UserAllocated;
    _res["Dirty"] = Dirty;
    return _res;
}

