void ADFTypes::AttachedEffectTableData::read(IO::File& buffer) {
    Base.read(buffer);
    for(int i = 0; i < 32; ++i) {
        Effects[i] = buffer.read_pod<uint32>();
    }
    for(int i = 0; i < 32; ++i) {
        Sounds[i].read(buffer);
    }
    EffectParams.read(buffer);
    SoundParams.read(buffer);
}

void ADFTypes::AttachedEffectTableData::print(std::ostream &out) const {
    Base.print(out);
    out << "Effects: \n";
    Effects.print(out);
    out << "\n";
    out << "Sounds: \n";
    Sounds.print(out);
    out << "\n";
    out << "EffectParams: \n";
    EffectParams.print(out);
    out << "\n";
    out << "SoundParams: \n";
    SoundParams.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::AttachedEffectTableData::to_json() const {
    nlohmann::json _res;
    _res["Base"] = Base.to_json();
    _res["Effects"] = Effects.to_json();
    _res["Sounds"] = Sounds.to_json();
    _res["EffectParams"] = EffectParams.to_json();
    _res["SoundParams"] = SoundParams.to_json();
    return _res;
}

