void ADFTypes::_ExtrudableObjectData::read(IO::File& buffer) {
    segments_override = buffer.read_pod<uint8>();
    cast_shadows = buffer.read_pod<uint8>();
    buffer.skip(6);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        diffuse_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    segments = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        normal_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 2; ++i) {
        texture_tiling[i] = buffer.read_pod<float32>();
    }
    extrude = buffer.read_pod<uint8>();
    buffer.skip(3);
    radius = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        properties_texture = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    sides = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::_ExtrudableObjectData::print(std::ostream &out) const {
    out << "segments_override: " << segments_override << "\n";
    out << "cast_shadows: " << cast_shadows << "\n";
    out << "diffuse_texture: " << diffuse_texture << "\n";
    out << "segments: " << segments << "\n";
    out << "normal_texture: " << normal_texture << "\n";
    out << "texture_tiling: \n";
    texture_tiling.print(out);
    out << "\n";
    out << "extrude: " << extrude << "\n";
    out << "radius: " << radius << "\n";
    out << "properties_texture: " << properties_texture << "\n";
    out << "sides: " << sides << "\n";
}

nlohmann::json ADFTypes::_ExtrudableObjectData::to_json() const {
    nlohmann::json _res;
    _res["segments_override"] = segments_override;
    _res["cast_shadows"] = cast_shadows;
    _res["diffuse_texture"] = diffuse_texture;
    _res["segments"] = segments;
    _res["normal_texture"] = normal_texture;
    _res["texture_tiling"] = texture_tiling.to_json();
    _res["extrude"] = extrude;
    _res["radius"] = radius;
    _res["properties_texture"] = properties_texture;
    _res["sides"] = sides;
    return _res;
}

