void ADFTypes::GenericVehicleCamera::read(IO::File& buffer) {
    StateTransitionTime = buffer.read_pod<float32>();
    TransitionToCrashStateDelay = buffer.read_pod<float32>();
    DriftTransitionTime = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        CameraPosition[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        CrashingCameraPosition[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        RotationPoint[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        LookAtPoint[i] = buffer.read_pod<float32>();
    }
    LookAtReferenceWheelbaseRatio = buffer.read_pod<float32>();
    AddLookAtPointToPositionRatio = buffer.read_pod<float32>();
    VelDirBlendWithVehicleDirSpeed = buffer.read_pod<float32>();
    DrivingVelocityMatrixBlend = buffer.read_pod<float32>();
    MinTimeForHalfTurn = buffer.read_pod<float32>();
    YawSpringStiffness = buffer.read_pod<float32>();
    DriftYawSpringStiffness = buffer.read_pod<float32>();
    YawSpringAngleLimit = buffer.read_pod<float32>();
    YawSpringLimitStiffnessPower = buffer.read_pod<float32>();
    YawSpringStiffnessMax = buffer.read_pod<float32>();
    PitchSpringStiffness = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        PitchLimit[i] = buffer.read_pod<float32>();
    }
    RollSpringStiffness = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        RollLimit[i] = buffer.read_pod<float32>();
    }
    LagSpring.read(buffer);
    LagCameraRelativity = buffer.read_pod<float32>();
    LagVelocityScale = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        FollowCameraRange[i] = buffer.read_pod<float32>();
    }
    CameraVelocitySpring.read(buffer);
    LookAtVelocitySpring.read(buffer);
    UpCameraVelocityRefSpeedKph = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        UpCameraRange[i] = buffer.read_pod<float32>();
    }
    UpLookAtVelocityRefSpeedKph = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        UpLookAtRange[i] = buffer.read_pod<float32>();
    }
    RightCameraVelocityRefSpeedKph = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        RightCameraRange[i] = buffer.read_pod<float32>();
    }
    RightLookAtVelocityRefSpeedKph = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        RightLookAtRange[i] = buffer.read_pod<float32>();
    }
    RollWithVehicleAmount = buffer.read_pod<float32>();
    ReCenterDelay = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        ReCenterSpeed[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        ReCenterAcceleration[i] = buffer.read_pod<float32>();
    }
    ReCenterPitchThreshold = buffer.read_pod<float32>();
    ReCenterYawThreshold = buffer.read_pod<float32>();
    ReCenterDeadZoneDelay = buffer.read_pod<float32>();
    ReCenterEaseOutTime = buffer.read_pod<float32>();
    RecenterEaseOutMinSpeed = buffer.read_pod<float32>();
    WeaponFireReCenterDelay = buffer.read_pod<float32>();
    AccelerationLerpSpeed = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        AccelerationOffset[i] = buffer.read_pod<float32>();
    }
    BoostLerpSpeed = buffer.read_pod<float32>();
    BoostAddedFOV = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        BoostOffset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        SpeedOffset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        FOVVelocityRange[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        FOV[i] = buffer.read_pod<float32>();
    }
    FOVBlendSpring.read(buffer);
    FOVCompensationStrength = buffer.read_pod<float32>();
    FOVZoomAdjustment = buffer.read_pod<float32>();
    CollisionBlendSpring.read(buffer);
    CollisionFudgeFactor = buffer.read_pod<float32>();
    CollisionPitchEnabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    CollisionCheckWater = buffer.read_pod<uint32>();
    for(int i = 0; i < 3; ++i) {
        CollisionStartPoint[i] = buffer.read_pod<float32>();
    }
    TowingOffsets.read(buffer);
    AlignReferenceWithWorldUp = buffer.read_pod<uint8>();
    buffer.skip(3);
    DrawDebugInfo = buffer.read_pod<uint32>();
    ListenerHeadRelativity = buffer.read_pod<float32>();
    InputSettings.read(buffer);
    SplineFuncOfPitchParams.read(buffer);
    MouseSensistivityX = buffer.read_pod<float32>();
    MouseSensistivityY = buffer.read_pod<float32>();
    VehicleBaseTransformSmoothYawSpeed = buffer.read_pod<float32>();
    VehicleBaseTransformSmoothPitchSpeed = buffer.read_pod<float32>();
    VehicleBaseTransformSmoothRollSpeed = buffer.read_pod<float32>();
}

