void ADFTypes::CItemMeleeWeaponData::read(IO::File& buffer) {
    ParentCItemObject = std::move(Deferred::read(buffer));
    for(int i = 0; i < 3; ++i) {
        sweep_center[i] = buffer.read_pod<float32>();
    }
    time_limit = buffer.read_pod<float32>();
    sweep_on_enter_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        on_hit_intended_target_bb_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        on_hit_world_bb_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    damage = buffer.read_pod<int32>();
    buffer.skip(4);
    force_pulse_ref.read(buffer);
    ignore_players = buffer.read_pod<uint8>();
    buffer.skip(3);
    sweep_radius = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        spell = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    shatter = buffer.read_pod<float32>();
    buffer.skip(4);
    sweep_on_exit_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        on_hit_target_bb_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    knockback_velocity_y_addition = buffer.read_pod<float32>();
    attack_effect_hidden_in_cine_cam_mode = buffer.read_pod<uint8>();
    do_knockback = buffer.read_pod<uint8>();
    buffer.skip(2);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        intended_target_bb_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    stagger = buffer.read_pod<float32>();
    knockback_velocity = buffer.read_pod<float32>();
}

void ADFTypes::CItemMeleeWeaponData::print(std::ostream &out) const {
    out << "ParentCItemObject: " << "\n";
    if (ParentCItemObject) {
        ParentCItemObject->print(out);
    }
    out << "sweep_center: \n";
    sweep_center.print(out);
    out << "\n";
    out << "time_limit: " << time_limit << "\n";
    sweep_on_enter_event.print(out);
    out << "on_hit_intended_target_bb_key: " << on_hit_intended_target_bb_key << "\n";
    out << "on_hit_world_bb_key: " << on_hit_world_bb_key << "\n";
    out << "damage: " << damage << "\n";
    force_pulse_ref.print(out);
    out << "ignore_players: " << ignore_players << "\n";
    out << "sweep_radius: " << sweep_radius << "\n";
    out << "spell: " << spell << "\n";
    out << "shatter: " << shatter << "\n";
    sweep_on_exit_event.print(out);
    out << "on_hit_target_bb_key: " << on_hit_target_bb_key << "\n";
    out << "knockback_velocity_y_addition: " << knockback_velocity_y_addition << "\n";
    out << "attack_effect_hidden_in_cine_cam_mode: " << attack_effect_hidden_in_cine_cam_mode << "\n";
    out << "do_knockback: " << do_knockback << "\n";
    out << "name: " << name << "\n";
    out << "intended_target_bb_key: " << intended_target_bb_key << "\n";
    out << "stagger: " << stagger << "\n";
    out << "knockback_velocity: " << knockback_velocity << "\n";
}

