void ADFTypes::CAnimLFOData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    enable_event.read(buffer);
    rotation_y_frequency_alternate = buffer.read_pod<float32>();
    stop_ramp_time = buffer.read_pod<float32>();
    translation_x_frequency_alternate = buffer.read_pod<float32>();
    shape = buffer.read_pod<int32>();
    translation_y_frequency_alternate = buffer.read_pod<float32>();
    rotation_x_frequency = buffer.read_pod<float32>();
    rotation_y_amplitude = buffer.read_pod<float32>();
    translation_y_frequency = buffer.read_pod<float32>();
    rotation_z_amplitude = buffer.read_pod<float32>();
    stop_at_init_pos_on_disable = buffer.read_pod<uint8>();
    buffer.skip(3);
    rotation_x_amplitude = buffer.read_pod<float32>();
    start_ramp_time = buffer.read_pod<float32>();
    rotation_z_amplitude_alternate = buffer.read_pod<float32>();
    translation_x_amplitude_alternate = buffer.read_pod<float32>();
    disable_event.read(buffer);
    rotation_y_amplitude_alternate = buffer.read_pod<float32>();
    rotation_z_frequency_alternate = buffer.read_pod<float32>();
    rotation_x_amplitude_alternate = buffer.read_pod<float32>();
    direction = buffer.read_pod<int32>();
    smooth_frequency_change = buffer.read_pod<uint8>();
    buffer.skip(3);
    translation_x_amplitude = buffer.read_pod<float32>();
    translation_z_amplitude = buffer.read_pod<float32>();
    translation_z_frequency_alternate = buffer.read_pod<float32>();
    translation_z_amplitude_alternate = buffer.read_pod<float32>();
    rotation_x_frequency_alternate = buffer.read_pod<float32>();
    rotation_z_frequency = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    translation_z_frequency = buffer.read_pod<float32>();
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    translation_y_amplitude = buffer.read_pod<float32>();
    rotation_y_frequency = buffer.read_pod<float32>();
    translation_x_frequency = buffer.read_pod<float32>();
    translation_y_amplitude_alternate = buffer.read_pod<float32>();
}

