void ADFTypes::LocalAngleLimitsModifierParams::read(IO::File& buffer) {
    BypassModifier = buffer.read_pod<uint8>();
    DisablePitchLimits = buffer.read_pod<uint8>();
    buffer.skip(2);
    for(int i = 0; i < 2; ++i) {
        PitchLimit[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        PitchLimitSmoothing[i] = buffer.read_pod<float32>();
    }
    DisableYawLimits = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 2; ++i) {
        YawLimit[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        YawLimitSmoothing[i] = buffer.read_pod<float32>();
    }
    UsePlayerCharacterRootPitch = buffer.read_pod<uint8>();
    buffer.skip(3);
}

