void ADFTypes::CSBLootPackageData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    SLootPackageEntryArray.read(buffer);
    SCosmeticRewardEntryArray.read(buffer);
    chance_of_material_drops = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    show_in_ui = buffer.read_pod<uint8>();
    give_all_rewards = buffer.read_pod<uint8>();
    buffer.skip(2);
    package_size = buffer.read_pod<int32>();
    fallback_package = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        portrait = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    package_star_rating = buffer.read_pod<int32>();
    gui_name = buffer.read_pod<uint32>();
}

