void ADFTypes::CCombatantWaveRuleData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    SSpawnPointArray.read(buffer);
    SSoundCSendFunctionArray.read(buffer);
    enable_event.read(buffer);
    on_hit_event.read(buffer);
    make_invulnerable_event.read(buffer);
    on_despawn_event.read(buffer);
    on_world_at_war_death_event.read(buffer);
    restore_health_event.read(buffer);
    proximity_check = buffer.read_pod<uint8>();
    buffer.skip(7);
    disable_invulnerable_to_other_ai.read(buffer);
    force_death_event.read(buffer);
    disable_event.read(buffer);
    initial_interest = buffer.read_pod<int32>();
    buffer.skip(4);
    override_target.read(buffer);
    enable_invulnerable_to_other_ai.read(buffer);
    on_death_event.read(buffer);
    on_spawn_event.read(buffer);
    block_check = buffer.read_pod<uint8>();
    los_check = buffer.read_pod<uint8>();
    buffer.skip(2);
    faction = buffer.read_pod<int32>();
    change_character_faction_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    drop_to_one_hp_event.read(buffer);
    invulnerable_to_other_ai = buffer.read_pod<uint8>();
    invulnerable = buffer.read_pod<uint8>();
    buffer.skip(6);
    make_vulnerable_event.read(buffer);
}

