void ADFTypes::SIKBbBallJointData::read(IO::File& buffer) {
    ParentCEditorTransformable = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    master_gain = buffer.read_pod<float32>();
    joint_strength = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        target_position_blackboard_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        at_vector[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    use_model_space = buffer.read_pod<uint8>();
    buffer.skip(3);
    max_angle = buffer.read_pod<float32>();
}

void ADFTypes::SIKBbBallJointData::print(std::ostream &out) const {
    out << "ParentCEditorTransformable: " << "\n";
    if (ParentCEditorTransformable) {
        ParentCEditorTransformable->print(out);
    }
    out << "name: " << name << "\n";
    out << "master_gain: " << master_gain << "\n";
    out << "joint_strength: " << joint_strength << "\n";
    out << "target_position_blackboard_key: " << target_position_blackboard_key << "\n";
    out << "at_vector: \n";
    at_vector.print(out);
    out << "\n";
    out << "joint: " << joint << "\n";
    out << "use_model_space: " << use_model_space << "\n";
    out << "max_angle: " << max_angle << "\n";
}

nlohmann::json ADFTypes::SIKBbBallJointData::to_json() const {
    nlohmann::json _res;
    if (ParentCEditorTransformable) {
        _res["ParentCEditorTransformable"] = ParentCEditorTransformable->to_json();
    }
    _res["name"] = name;
    _res["master_gain"] = master_gain;
    _res["joint_strength"] = joint_strength;
    _res["target_position_blackboard_key"] = target_position_blackboard_key;
    _res["at_vector"] = at_vector.to_json();
    _res["joint"] = joint;
    _res["use_model_space"] = use_model_space;
    _res["max_angle"] = max_angle;
    return _res;
}

