void ADFTypes::CImpactDamagerData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    enable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        spell_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    min_speed = buffer.read_pod<float32>();
    buffer.skip(4);
    on_damage_event.read(buffer);
    disable_event.read(buffer);
}

