    _terrain_control_point_left_padding.read(buffer);
    sidewalk_left = buffer.read_pod<float32>();
    traverse_type = buffer.read_pod<int32>();
    material_id = buffer.read_pod<int32>();
    buffer.skip(4);
    _terrain_control_point_left_slope.read(buffer);
