    buffer.skip(3);
    _terrain_control_point_right_slope.read(buffer);
    generate_material_primitive = buffer.read_pod<uint8>();
    buffer.skip(3);
    road_type = buffer.read_pod<int32>();
    traffic_scalar = buffer.read_pod<float32>();
    terrain_falloff_noise = buffer.read_pod<float32>();
    is_visible = buffer.read_pod<uint8>();
    buffer.skip(3);
    terrain_slope = buffer.read_pod<float32>();
    terrain_tunnel_noise = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    terrain_depth_scale = buffer.read_pod<float32>();
    buffer.skip(4);
    _layer3.read(buffer);
    _layer2.read(buffer);
    _layer4.read(buffer);
    speed_limit = buffer.read_pod<int32>();
    tunnel_material_id = buffer.read_pod<int32>();
    _texture_index.read(buffer);
    flags = buffer.read_pod<int32>();
    sidewalk_offset_left = buffer.read_pod<float32>();
    _prototype0.read(buffer);
    _banking.read(buffer);
    valid = buffer.read_pod<uint8>();
    buffer.skip(3);
    decoration_set = buffer.read_pod<int32>();
