void ADFTypes::CSoundOcclusionBoxData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    inverted_normal = buffer.read_pod<uint8>();
    disable_yz0_plane = buffer.read_pod<uint8>();
    buffer.skip(6);
    event_enable_xz0_plane.read(buffer);
    event_disable_yz0_plane.read(buffer);
    disable_xy0_plane = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_enable_xy0_plane.read(buffer);
    size_x = buffer.read_pod<float32>();
    occlusion_reverb_mix = buffer.read_pod<float32>();
    size_z = buffer.read_pod<float32>();
    occlusion_direct_path = buffer.read_pod<float32>();
    event_disable_xz0_plane.read(buffer);
    event_disable_yz1_plane.read(buffer);
    event_disable_xz1_plane.read(buffer);
    event_enable_yz1_plane.read(buffer);
    event_receive_matrix.read(buffer);
    event_enable_xy1_plane.read(buffer);
    disable_yz1_plane = buffer.read_pod<uint8>();
    disable_xz0_plane = buffer.read_pod<uint8>();
    buffer.skip(2);
    _exportable = buffer.read_pod<int32>();
    disable_xy1_plane = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_disable.read(buffer);
    dynamic_scaling = buffer.read_pod<float32>();
    buffer.skip(4);
    event_enable.read(buffer);
    event_disable_xy0_plane.read(buffer);
    event_enable_xz1_plane.read(buffer);
    event_enable_dynamic_scaling.read(buffer);
    event_enable_yz0_plane.read(buffer);
    event_disable_dynamic_scaling.read(buffer);
    double_sided = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_disable_xy1_plane.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<uint8>();
    disable_xz1_plane = buffer.read_pod<uint8>();
    buffer.skip(2);
    size_y = buffer.read_pod<float32>();
}

