void ADFTypes::SConstraintPointData::read(IO::File& buffer) {
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        target_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        target_offset[i] = buffer.read_pod<float32>();
    }
    axis_x = buffer.read_pod<uint8>();
    axis_y = buffer.read_pod<uint8>();
    axis_z = buffer.read_pod<uint8>();
    buffer.skip(1);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        constrained_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::SConstraintPointData::print(std::ostream &out) const {
    out << "name: " << name << "\n";
    out << "target_joint: " << target_joint << "\n";
    out << "target_offset: \n";
    target_offset.print(out);
    out << "\n";
    out << "axis_x: " << axis_x << "\n";
    out << "axis_y: " << axis_y << "\n";
    out << "axis_z: " << axis_z << "\n";
    out << "constrained_joint: " << constrained_joint << "\n";
}

nlohmann::json ADFTypes::SConstraintPointData::to_json() const {
    nlohmann::json _res;
    _res["name"] = name;
    _res["target_joint"] = target_joint;
    _res["target_offset"] = target_offset.to_json();
    _res["axis_x"] = axis_x;
    _res["axis_y"] = axis_y;
    _res["axis_z"] = axis_z;
    _res["constrained_joint"] = constrained_joint;
    return _res;
}

