void ADFTypes::CNpcSupportItemDamagingEffectData::read(IO::File& buffer) {
    ParentCNpcSupportItem = std::move(Deferred::read(buffer));
    effect_emitter_ref.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        damage_offset[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        spell_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 16; ++i) {
        effect_offset[i] = buffer.read_pod<float32>();
    }
    damage_radius = buffer.read_pod<float32>();
    buffer.skip(4);
}

void ADFTypes::CNpcSupportItemDamagingEffectData::print(std::ostream &out) const {
    out << "ParentCNpcSupportItem: " << "\n";
    if (ParentCNpcSupportItem) {
        ParentCNpcSupportItem->print(out);
    }
    effect_emitter_ref.print(out);
    out << "name: " << name << "\n";
    out << "damage_offset: \n";
    damage_offset.print(out);
    out << "\n";
    out << "spell_id: " << spell_id << "\n";
    out << "effect_offset: \n";
    effect_offset.print(out);
    out << "\n";
    out << "damage_radius: " << damage_radius << "\n";
}

nlohmann::json ADFTypes::CNpcSupportItemDamagingEffectData::to_json() const {
    nlohmann::json _res;
    if (ParentCNpcSupportItem) {
        _res["ParentCNpcSupportItem"] = ParentCNpcSupportItem->to_json();
    }
    _res["effect_emitter_ref"] = effect_emitter_ref.to_json();
    _res["name"] = name;
    _res["damage_offset"] = damage_offset.to_json();
    _res["spell_id"] = spell_id;
    _res["effect_offset"] = effect_offset.to_json();
    _res["damage_radius"] = damage_radius;
    return _res;
}

