void ADFTypes::CSignalSourceData::read(IO::File& buffer) {
    Parent_CSaveInfo = std::move(Deferred::read(buffer));
    ParentCTransformObject = std::move(Deferred::read(buffer));
    display_text = buffer.read_pod<uint32>();
    buffer.skip(4);
    on_start_tracking_event.read(buffer);
    min_signal_distance = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_enter_event.read(buffer);
    enabled = buffer.read_pod<uint8>();
    buffer.skip(7);
    on_stop_tracking_event.read(buffer);
    on_exit_event.read(buffer);
    max_signal_distance = buffer.read_pod<float32>();
    signal_priority = buffer.read_pod<int32>();
    enable_event.read(buffer);
    save = buffer.read_pod<uint8>();
    buffer.skip(7);
    disable_event.read(buffer);
}

void ADFTypes::CSignalSourceData::print(std::ostream &out) const {
    out << "Parent_CSaveInfo: " << "\n";
    if (Parent_CSaveInfo) {
        Parent_CSaveInfo->print(out);
    }
    out << "ParentCTransformObject: " << "\n";
    if (ParentCTransformObject) {
        ParentCTransformObject->print(out);
    }
    out << "display_text: " << display_text << "\n";
    on_start_tracking_event.print(out);
    out << "min_signal_distance: " << min_signal_distance << "\n";
    out << "name: " << name << "\n";
    on_enter_event.print(out);
    out << "enabled: " << enabled << "\n";
    on_stop_tracking_event.print(out);
    on_exit_event.print(out);
    out << "max_signal_distance: " << max_signal_distance << "\n";
    out << "signal_priority: " << signal_priority << "\n";
    enable_event.print(out);
    out << "save: " << save << "\n";
    disable_event.print(out);
}

nlohmann::json ADFTypes::CSignalSourceData::to_json() const {
    nlohmann::json _res;
    if (Parent_CSaveInfo) {
        _res["Parent_CSaveInfo"] = Parent_CSaveInfo->to_json();
    }
    if (ParentCTransformObject) {
        _res["ParentCTransformObject"] = ParentCTransformObject->to_json();
    }
    _res["display_text"] = display_text;
    _res["on_start_tracking_event"] = on_start_tracking_event.to_json();
    _res["min_signal_distance"] = min_signal_distance;
    _res["name"] = name;
    _res["on_enter_event"] = on_enter_event.to_json();
    _res["enabled"] = enabled;
    _res["on_stop_tracking_event"] = on_stop_tracking_event.to_json();
    _res["on_exit_event"] = on_exit_event.to_json();
    _res["max_signal_distance"] = max_signal_distance;
    _res["signal_priority"] = signal_priority;
    _res["enable_event"] = enable_event.to_json();
    _res["save"] = save;
    _res["disable_event"] = disable_event.to_json();
    return _res;
}

