void ADFTypes::EyeGlossConstants::read(IO::File& buffer) {
    EyeGlossiness = buffer.read_pod<float32>();
    EyeSpecularIntensity = buffer.read_pod<float32>();
    EyeReflectIntensity = buffer.read_pod<float32>();
    EyeReflectThreshold = buffer.read_pod<float32>();
    EyeGlossShadowIntensity = buffer.read_pod<float32>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        CustomEyeReflectionCube = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

