void ADFTypes::CAnimRotationData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    SReplicationParams = std::move(Deferred::read(buffer));
    acceleration_time = buffer.read_pod<float32>();
    buffer.skip(4);
    decrease_animation_speed.read(buffer);
    random_offset = buffer.read_pod<float32>();
    buffer.skip(4);
    on_stop.read(buffer);
    noise_frequency = buffer.read_pod<float32>();
    buffer.skip(4);
    reset_animation_speed.read(buffer);
    rotation_axis = buffer.read_pod<int32>();
    noise_chaos = buffer.read_pod<float32>();
    start_end_connected = buffer.read_pod<uint8>();
    buffer.skip(7);
    at_start.read(buffer);
    angle = buffer.read_pod<int32>();
    animation_speed = buffer.read_pod<float32>();
    start.read(buffer);
    loop_mode = buffer.read_pod<int32>();
    noise = buffer.read_pod<uint8>();
    buffer.skip(3);
    stop.read(buffer);
    deceleration_time = buffer.read_pod<float32>();
    noise_amplitude = buffer.read_pod<float32>();
    offset = buffer.read_pod<float32>();
    easing_curve = buffer.read_pod<int32>();
    loop_count = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    reset.read(buffer);
    reverse.read(buffer);
    enabled_from_start = buffer.read_pod<uint8>();
    buffer.skip(3);
    animation_speed_change = buffer.read_pod<float32>();
    persistent = buffer.read_pod<uint8>();
    buffer.skip(7);
    at_end.read(buffer);
    increase_animation_speed.read(buffer);
}

