    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "SReplicationParams: " << "\n";
    if (SReplicationParams) {
        SReplicationParams->print(out);
    }
    out << "acceleration_time: " << acceleration_time << "\n";
    decrease_animation_speed.print(out);
    out << "random_offset: " << random_offset << "\n";
    on_stop.print(out);
    out << "noise_frequency: " << noise_frequency << "\n";
    reset_animation_speed.print(out);
    out << "rotation_axis: " << rotation_axis << "\n";
    out << "noise_chaos: " << noise_chaos << "\n";
    out << "start_end_connected: " << start_end_connected << "\n";
    at_start.print(out);
    out << "angle: " << angle << "\n";
    out << "animation_speed: " << animation_speed << "\n";
    start.print(out);
    out << "loop_mode: " << loop_mode << "\n";
    out << "noise: " << noise << "\n";
    stop.print(out);
    out << "deceleration_time: " << deceleration_time << "\n";
    out << "noise_amplitude: " << noise_amplitude << "\n";
    out << "offset: " << offset << "\n";
    out << "easing_curve: " << easing_curve << "\n";
    out << "loop_count: " << loop_count << "\n";
    out << "name: " << name << "\n";
