void ADFTypes::CCivilianRuleData::read(IO::File& buffer) {
    ParentCCharacterLodFeatures = std::move(Deferred::read(buffer));
    ParentCSpawnRule = std::move(Deferred::read(buffer));
    SShapeDefArray.read(buffer);
    spawn_road_search_distance = buffer.read_pod<float32>();
    buffer.skip(4);
    on_hit_event.read(buffer);
    spawn_tags.read(buffer);
    spawn_allow_in_air = buffer.read_pod<uint8>();
    buffer.skip(3);
    spawn_chance = buffer.read_pod<float32>();
    unload_auto_despawn = buffer.read_pod<uint8>();
    spawn_float_on_water = buffer.read_pod<uint8>();
    buffer.skip(2);
    priority = buffer.read_pod<int32>();
    spawn_road_search_test_distance_from_max = buffer.read_pod<float32>();
    spawn_road_search_test_from_driveable_runoff = buffer.read_pod<uint8>();
    buffer.skip(3);
    spawn_road_search_test_distance_from_min = buffer.read_pod<float32>();
    spawn_max_ground_slope = buffer.read_pod<float32>();
    on_death_event.read(buffer);
    faction = buffer.read_pod<int32>();
    spawn_reject_in_water = buffer.read_pod<uint8>();
    buffer.skip(3);
    spawn_min_distance_to_roads = buffer.read_pod<float32>();
    buffer.skip(4);
    deactivate_event.read(buffer);
    despawn_event.read(buffer);
    spawn_count = buffer.read_pod<int32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    spawn_road_search_test_from_runoff_start = buffer.read_pod<uint8>();
    spawn_road_search_test_from_edge_start = buffer.read_pod<uint8>();
    spawn_road_search_invert_result = buffer.read_pod<uint8>();
    buffer.skip(5);
    activate_event.read(buffer);
}

