void ADFTypes::SSoundModuleConditionalFunctionsData::read(IO::File& buffer) {
    ParentSSoundModuleComponentBase = std::move(Deferred::read(buffer));
    SSoundModuleConditions = std::move(Deferred::read(buffer));
    SSoundModuleFunctions = std::move(Deferred::read(buffer));
    _exportable = buffer.read_pod<int32>();
    buffer.skip(4);
}

