void ADFTypes::CMissionStatusRouterData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    check_status_event.read(buffer);
    true_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        mission_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    false_event.read(buffer);
    status_type = buffer.read_pod<int32>();
    check_on_creation = buffer.read_pod<uint8>();
    buffer.skip(3);
}

void ADFTypes::CMissionStatusRouterData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "name: " << name << "\n";
    check_status_event.print(out);
    true_event.print(out);
    out << "mission_id: " << mission_id << "\n";
    false_event.print(out);
    out << "status_type: " << status_type << "\n";
    out << "check_on_creation: " << check_on_creation << "\n";
}

nlohmann::json ADFTypes::CMissionStatusRouterData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    _res["name"] = name;
    _res["check_status_event"] = check_status_event.to_json();
    _res["true_event"] = true_event.to_json();
    _res["mission_id"] = mission_id;
    _res["false_event"] = false_event.to_json();
    _res["status_type"] = status_type;
    _res["check_on_creation"] = check_on_creation;
    return _res;
}

