void ADFTypes::RigidBody::read(IO::File& buffer) {
    mass = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        center_of_mass[i] = buffer.read_pod<float32>();
    }
    center_of_mass_bias = buffer.read_pod<float32>();
    unit_inertia_yaw = buffer.read_pod<float32>();
    unit_inertia_pitch = buffer.read_pod<float32>();
    unit_inertia_roll = buffer.read_pod<float32>();
    linear_damping = buffer.read_pod<float32>();
    angular_damping = buffer.read_pod<float32>();
    max_angular_velocity = buffer.read_pod<float32>();
    max_linear_velocity = buffer.read_pod<float32>();
    use_calculated_inertia = buffer.read_pod<int32>();
    add_drivers_mass = buffer.read_pod<int32>();
    for(int i = 0; i < 3; ++i) {
        driver_center_of_mass[i] = buffer.read_pod<float32>();
    }
}

