void ADFTypes::CForceFieldData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    SShapeTriggerExtensionArray.read(buffer);
    force_direction_noise_angle = buffer.read_pod<float32>();
    force = buffer.read_pod<float32>();
    field_reversed = buffer.read_pod<uint8>();
    buffer.skip(3);
    target_velocity = buffer.read_pod<float32>();
    subject_ref.read(buffer);
    subject_script_tags.read(buffer);
    affect_npc_dead = buffer.read_pod<uint8>();
    buffer.skip(3);
    acceleration = buffer.read_pod<float32>();
    field_type = buffer.read_pod<int32>();
    debug_draw_shape = buffer.read_pod<uint8>();
    buffer.skip(3);
    reverse_field.read(buffer);
    closest_point_to_COM_scale = buffer.read_pod<float32>();
    target_angular_velocity = buffer.read_pod<float32>();
    subject_exclude_ref.read(buffer);
    affect_vehicle = buffer.read_pod<uint8>();
    buffer.skip(3);
    force_falloff_begin_distance = buffer.read_pod<float32>();
    enable.read(buffer);
    force_falloff_end_distance = buffer.read_pod<float32>();
    per_object_acceleration = buffer.read_pod<float32>();
    receive_matrix_event.read(buffer);
    subject_exclude_script_tags.read(buffer);
    disable.read(buffer);
    force_falloff_end_scale = buffer.read_pod<float32>();
    affect_rigid_object = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    closest_point_to_COM_scale_random_size = buffer.read_pod<float32>();
}

