void ADFTypes::Transmission::read(IO::File& buffer) {
    gears = buffer.read_pod<int32>();
    nitrous_gears = buffer.read_pod<int32>();
    heat_boost_gears = buffer.read_pod<int32>();
    for(int i = 0; i < 8; ++i) {
        gear_ratios[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 8; ++i) {
        upshift_rpm[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 8; ++i) {
        downshift_rpm[i] = buffer.read_pod<float32>();
    }
    sequential = buffer.read_pod<int32>();
    manual_clutch = buffer.read_pod<int32>();
    manual_clutch_blend_rpm = buffer.read_pod<float32>();
    manual_clutch_blend_time = buffer.read_pod<float32>();
    forward_ratio_percentage = buffer.read_pod<float32>();
    low_gear_forward_ratio_pct = buffer.read_pod<float32>();
    top_speed = buffer.read_pod<float32>();
    low_gears_final_drive = buffer.read_pod<float32>();
    final_drive = buffer.read_pod<float32>();
    reverse_uses_forward_gears = buffer.read_pod<int32>();
    reverse_gear_ratio = buffer.read_pod<float32>();
    clutch_delay = buffer.read_pod<float32>();
    decay_time_to_cruise_rpm = buffer.read_pod<float32>();
    target_cruise_rpm = buffer.read_pod<float32>();
}

