void ADFTypes::CBoxVolumeObjectData::read(IO::File& buffer) {
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _exportable = buffer.read_pod<int32>();
    buffer.skip(4);
}

void ADFTypes::CBoxVolumeObjectData::print(std::ostream &out) const {
    out << "ParentCScaleTransformable: " << "\n";
    if (ParentCScaleTransformable) {
        ParentCScaleTransformable->print(out);
    }
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "name: " << name << "\n";
    out << "_exportable: " << _exportable << "\n";
}

nlohmann::json ADFTypes::CBoxVolumeObjectData::to_json() const {
    nlohmann::json _res;
    if (ParentCScaleTransformable) {
        _res["ParentCScaleTransformable"] = ParentCScaleTransformable->to_json();
    }
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["name"] = name;
    _res["_exportable"] = _exportable;
    return _res;
}

