void ADFTypes::CCameraJointAttachmentModifierData::read(IO::File& buffer) {
    foreground_fov = buffer.read_pod<float32>();
    first_person_pass = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        joint_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        joint_translation_offset[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
}

