void ADFTypes::SkidAndRollExplosionSettings::read(IO::File& buffer) {
    trigger_weight = buffer.read_pod<float32>();
    trigger_speed_limit = buffer.read_pod<float32>();
    initial_explosion_usage.read(buffer);
    skid_speed = buffer.read_pod<float32>();
    skid_offset_x = buffer.read_pod<float32>();
    skid_offset_z = buffer.read_pod<float32>();
    flip_forward_speed = buffer.read_pod<float32>();
    flip_roll_speed = buffer.read_pod<float32>();
    flip_up_speed = buffer.read_pod<float32>();
    final_explosion_delay = buffer.read_pod<float32>();
    explosion_timeout = buffer.read_pod<float32>();
}

void ADFTypes::SkidAndRollExplosionSettings::print(std::ostream &out) const {
    out << "trigger_weight: " << trigger_weight << "\n";
    out << "trigger_speed_limit: " << trigger_speed_limit << "\n";
    initial_explosion_usage.print(out);
    out << "skid_speed: " << skid_speed << "\n";
    out << "skid_offset_x: " << skid_offset_x << "\n";
    out << "skid_offset_z: " << skid_offset_z << "\n";
    out << "flip_forward_speed: " << flip_forward_speed << "\n";
    out << "flip_roll_speed: " << flip_roll_speed << "\n";
    out << "flip_up_speed: " << flip_up_speed << "\n";
    out << "final_explosion_delay: " << final_explosion_delay << "\n";
    out << "explosion_timeout: " << explosion_timeout << "\n";
}

nlohmann::json ADFTypes::SkidAndRollExplosionSettings::to_json() const {
    nlohmann::json _res;
    _res["trigger_weight"] = trigger_weight;
    _res["trigger_speed_limit"] = trigger_speed_limit;
    _res["initial_explosion_usage"] = initial_explosion_usage.to_json();
    _res["skid_speed"] = skid_speed;
    _res["skid_offset_x"] = skid_offset_x;
    _res["skid_offset_z"] = skid_offset_z;
    _res["flip_forward_speed"] = flip_forward_speed;
    _res["flip_roll_speed"] = flip_roll_speed;
    _res["flip_up_speed"] = flip_up_speed;
    _res["final_explosion_delay"] = final_explosion_delay;
    _res["explosion_timeout"] = explosion_timeout;
    return _res;
}

static std::unique_ptr<ADFTypes::SkidAndRollExplosionSettings> SkidAndRollExplosionSettings_new_instance() {
    return std::make_unique<ADFTypes::SkidAndRollExplosionSettings>();
}

