void ADFTypes::CSunFlareData::read(IO::File& buffer) {
    ParentCEffectPointEmitter = std::move(Deferred::read(buffer));
    SunDistance = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::CSunFlareData::print(std::ostream &out) const {
    out << "ParentCEffectPointEmitter: " << "\n";
    if (ParentCEffectPointEmitter) {
        ParentCEffectPointEmitter->print(out);
    }
    out << "SunDistance: " << SunDistance << "\n";
    out << "name: " << name << "\n";
}

nlohmann::json ADFTypes::CSunFlareData::to_json() const {
    nlohmann::json _res;
    if (ParentCEffectPointEmitter) {
        _res["ParentCEffectPointEmitter"] = ParentCEffectPointEmitter->to_json();
    }
    _res["SunDistance"] = SunDistance;
    _res["name"] = name;
    return _res;
}

