void ADFTypes::Rotor::read(IO::File& buffer) {
    physics_component_name.read(buffer);
    for(int i = 0; i < 3; ++i) {
        position[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        axis[i] = buffer.read_pod<float32>();
    }
    does_steer = buffer.read_pod<int32>();
    rotation_speed = buffer.read_pod<float32>();
    torque = buffer.read_pod<float32>();
    buffer.skip(4);
}

void ADFTypes::Rotor::print(std::ostream &out) const {
    physics_component_name.print(out);
    out << "position: \n";
    position.print(out);
    out << "\n";
    out << "axis: \n";
    axis.print(out);
    out << "\n";
    out << "does_steer: " << does_steer << "\n";
    out << "rotation_speed: " << rotation_speed << "\n";
    out << "torque: " << torque << "\n";
}

nlohmann::json ADFTypes::Rotor::to_json() const {
    nlohmann::json _res;
    _res["physics_component_name"] = physics_component_name.to_json();
    _res["position"] = position.to_json();
    _res["axis"] = axis.to_json();
    _res["does_steer"] = does_steer;
    _res["rotation_speed"] = rotation_speed;
    _res["torque"] = torque;
    return _res;
}

