void ADFTypes::CCameraTransitionData::read(IO::File& buffer) {
    Parent_CCameraTransitionBase = std::move(Deferred::read(buffer));
    CCameraConditionFov = std::move(Deferred::read(buffer));
    CCameraConditionDistance = std::move(Deferred::read(buffer));
    CCameraConditionRotation = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        settings_file = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _180_rule_cut_enabled = buffer.read_pod<uint8>();
    buffer.skip(7);
}

void ADFTypes::CCameraTransitionData::print(std::ostream &out) const {
    out << "Parent_CCameraTransitionBase: " << "\n";
    if (Parent_CCameraTransitionBase) {
        Parent_CCameraTransitionBase->print(out);
    }
    out << "CCameraConditionFov: " << "\n";
    if (CCameraConditionFov) {
        CCameraConditionFov->print(out);
    }
    out << "CCameraConditionDistance: " << "\n";
    if (CCameraConditionDistance) {
        CCameraConditionDistance->print(out);
    }
    out << "CCameraConditionRotation: " << "\n";
    if (CCameraConditionRotation) {
        CCameraConditionRotation->print(out);
    }
    out << "name: " << name << "\n";
    out << "settings_file: " << settings_file << "\n";
    out << "_180_rule_cut_enabled: " << _180_rule_cut_enabled << "\n";
}

nlohmann::json ADFTypes::CCameraTransitionData::to_json() const {
    nlohmann::json _res;
    if (Parent_CCameraTransitionBase) {
        _res["Parent_CCameraTransitionBase"] = Parent_CCameraTransitionBase->to_json();
    }
    if (CCameraConditionFov) {
        _res["CCameraConditionFov"] = CCameraConditionFov->to_json();
    }
    if (CCameraConditionDistance) {
        _res["CCameraConditionDistance"] = CCameraConditionDistance->to_json();
    }
    if (CCameraConditionRotation) {
        _res["CCameraConditionRotation"] = CCameraConditionRotation->to_json();
    }
    _res["name"] = name;
    _res["settings_file"] = settings_file;
    _res["_180_rule_cut_enabled"] = _180_rule_cut_enabled;
    return _res;
}

