    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    _res["available"] = available;
    _res["userdata"] = userdata;
    _res["num_players_max"] = num_players_max;
    _res["subtitle"] = subtitle;
    _res["name"] = name;
