    day_time_transition_time = buffer.read_pod<float32>();
    buffer.skip(4);
    pause_event.read(buffer);
    on_transition_complete.read(buffer);
    reset_speed_multiplicator.read(buffer);
    apply_on_event.read(buffer);
    increase_weather_severity = buffer.read_pod<float32>();
    set_day_time = buffer.read_pod<float32>();
    increase_weather_time = buffer.read_pod<float32>();
    speed_multiplicator = buffer.read_pod<float32>();
    apply_only_speed_multiplicator.read(buffer);
    weather_severity_transition_time = buffer.read_pod<float32>();
    lock_weather_preset = buffer.read_pod<uint32>();
    set_weather_time = buffer.read_pod<float32>();
