void ADFTypes::CCameraObjectData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    CCameraTransitionCollection = std::move(Deferred::read(buffer));
    CCameraModifierArray.read(buffer);
    CCameraLookAtTargetModifier = std::move(Deferred::read(buffer));
    CCameraAnimationModifier = std::move(Deferred::read(buffer));
    CCameraGlobalAttachmentModifier = std::move(Deferred::read(buffer));
    CTargetRelativeAngleLimitsModifier = std::move(Deferred::read(buffer));
    CCameraJointAttachmentModifier = std::move(Deferred::read(buffer));
    CCameraJointOffsetModifier = std::move(Deferred::read(buffer));
    CFirstPersonLookAtTargetCameraModifier = std::move(Deferred::read(buffer));
    CCameraBoundToCharacterModifier = std::move(Deferred::read(buffer));
    CPhotoModeCameraModifier = std::move(Deferred::read(buffer));
    CPhotoModeVehicleCameraModifier = std::move(Deferred::read(buffer));
    CCameraHurlModifier = std::move(Deferred::read(buffer));
    CCameraPlayerModelModifier = std::move(Deferred::read(buffer));
    DOFSmoothness = buffer.read_pod<float32>();
    lifetime = buffer.read_pod<float32>();
    MaxDOF = buffer.read_pod<float32>();
    MaxDOFOverall = buffer.read_pod<float32>();
    allow_default_camera_cut = buffer.read_pod<uint8>();
    buffer.skip(3);
    DOFSmoothnessNear = buffer.read_pod<float32>();
    Deactivate.read(buffer);
    VFX_HDR_Scale = buffer.read_pod<float32>();
    FOV = buffer.read_pod<float32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        reference_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    FocalDistance = buffer.read_pod<float32>();
    pop_after_camera_transition = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 16; ++i) {
        camera_offset[i] = buffer.read_pod<float32>();
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        transition_groups = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    MaxDOFNear = buffer.read_pod<float32>();
    buffer.skip(4);
    Activate.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    default_ = buffer.read_pod<uint8>();
    update_during_pause = buffer.read_pod<uint8>();
    buffer.skip(2);
    for(int i = 0; i < 2; ++i) {
        FocalDistanceAuto[i] = buffer.read_pod<float32>();
    }
    DOFHeightFalloff = buffer.read_pod<float32>();
    FocalDistanceNear = buffer.read_pod<float32>();
    buffer.skip(4);
}

