    _res["preset"] = preset.to_json();
    _res["terrain_height_blend_start"] = terrain_height_blend_start;
    _res["falloff"] = falloff;
    _res["y"] = y;
    _res["x"] = x;
    _res["z"] = z;
    _res["terrain_height_blend_end"] = terrain_height_blend_end;
    return _res;
