void ADFTypes::CSwarmControllerData::read(IO::File& buffer) {
    ParentCTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    target_character_ref.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    torque_limit = buffer.read_pod<float32>();
    buffer.skip(4);
    clone_factory_ref.read(buffer);
    point_light_ref.read(buffer);
    patrol_2_ref.read(buffer);
    evade_2_ref.read(buffer);
    evade_3_ref.read(buffer);
    do_eating = buffer.read_pod<uint8>();
    buffer.skip(7);
    patrol_1_ref.read(buffer);
    torque_factor = buffer.read_pod<float32>();
    buffer.skip(4);
    evade_1_ref.read(buffer);
    type = buffer.read_pod<int32>();
    buffer.skip(4);
    patrol_3_ref.read(buffer);
}

