void ADFTypes::VegetationPhysics::read(IO::File& buffer) {
    PfxFile.read(buffer);
    NavmeshPfxFile.read(buffer);
    StumpFile.read(buffer);
    PfxStumpFile.read(buffer);
    BrokenFile.read(buffer);
    BrokenPfxFile.read(buffer);
    PhysicsHandle = buffer.read_pod<uint16>();
    buffer.skip(2);
    ImpulseLimitPassThrough = buffer.read_pod<float32>();
    ImpulseThreshold = buffer.read_pod<float32>();
    BreakByBulletLimit = buffer.read_pod<float32>();
    BreakByExplosionLimit = buffer.read_pod<float32>();
    ExplosiveImpulseModifier = buffer.read_pod<float32>();
    AngularLimit = buffer.read_pod<float32>();
    Magnitude = buffer.read_pod<float32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        BreaksOnCollision = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        TerrainNormal = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        HasCollisions = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        FarModel = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        IsPebble = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        IgnorePlayer = (bitfield_value >> 5) & ((1ULL << 1) - 1);
        IsAiCover = (bitfield_value >> 6) & ((1ULL << 1) - 1);
    }
    StaticPathfinding = buffer.read_pod<uint8>();
    NavmeshUseHull2d = buffer.read_pod<uint8>();
    buffer.skip(5);
}

