void ADFTypes::CCameraPlayerModelModifierData::read(IO::File& buffer) {
    event_change_to_first_person.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_change_head_to_show.read(buffer);
    event_change_arms_to_show.read(buffer);
    show_body = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_change_to_world.read(buffer);
    event_change_head_to_hide.read(buffer);
    show_arms = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_change_body_to_show.read(buffer);
    first_person_renderpass_else_world = buffer.read_pod<uint8>();
    buffer.skip(7);
    event_change_arms_to_hide.read(buffer);
    event_change_body_to_hide.read(buffer);
    show_head = buffer.read_pod<uint8>();
    buffer.skip(7);
}

