void ADFTypes::WindowConstants::read(IO::File& buffer) {
    for(int i = 0; i < 3; ++i) {
        BaseTransmission[i] = buffer.read_pod<float32>();
    }
    MaxRoughness = buffer.read_pod<float32>();
    BaseBreakup = buffer.read_pod<float32>();
    BaseContrast = buffer.read_pod<float32>();
    SpecularFresnel = buffer.read_pod<float32>();
    NormalMapStrength = buffer.read_pod<float32>();
    DamagedRoughness = buffer.read_pod<float32>();
    DamagedSpecularFresnel = buffer.read_pod<float32>();
    Thickness = buffer.read_pod<float32>();
    DamageUVScale = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        DirtAlbedo[i] = buffer.read_pod<float32>();
    }
    DirtSpecularFresnel = buffer.read_pod<float32>();
    DirtUVScale = buffer.read_pod<float32>();
    DirtBreakup = buffer.read_pod<float32>();
    DirtContrast = buffer.read_pod<float32>();
    DirtMaxTransmission = buffer.read_pod<float32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        Simple = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        OneSided = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        Skinned = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        DirtLayerEnable = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        LensOcclusion = (bitfield_value >> 4) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
    UVAnimSpeedX = buffer.read_pod<float32>();
    UVAnimSpeedY = buffer.read_pod<float32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        UseAnim = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
}

