    out << "DirtAlbedo: \n";
    DirtAlbedo.print(out);
    out << "\n";
    out << "DirtSpecularFresnel: " << DirtSpecularFresnel << "\n";
    out << "DirtUVScale: " << DirtUVScale << "\n";
    out << "DirtBreakup: " << DirtBreakup << "\n";
