void ADFTypes::SPhysicsParamsData::read(IO::File& buffer) {
    layer = buffer.read_pod<int32>();
    side_area = buffer.read_pod<float32>();
    enable_buoyancy = buffer.read_pod<uint8>();
    override_mass = buffer.read_pod<uint8>();
    buffer.skip(2);
    radius = buffer.read_pod<float32>();
    puncturable = buffer.read_pod<uint8>();
    buffer.skip(3);
    buoyancy = buffer.read_pod<float32>();
    mass_category = buffer.read_pod<int32>();
    override_gravity = buffer.read_pod<uint8>();
    buffer.skip(3);
    drag_coefficient = buffer.read_pod<float32>();
    override_center_of_mass = buffer.read_pod<uint8>();
    buffer.skip(3);
    gravity = buffer.read_pod<float32>();
    max_angular_velocity = buffer.read_pod<float32>();
    floating_bobble = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 3; ++i) {
        center_of_mass[i] = buffer.read_pod<float32>();
    }
    debris_quality = buffer.read_pod<uint8>();
    buffer.skip(3);
    max_linear_velocity = buffer.read_pod<float32>();
    drag = buffer.read_pod<float32>();
    override_layer = buffer.read_pod<uint8>();
    buffer.skip(3);
    despawn_pool = buffer.read_pod<int32>();
    solver_stabilization = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    transparent_to_ai = buffer.read_pod<uint8>();
    buffer.skip(3);
    bottom_area = buffer.read_pod<float32>();
    angular_damping = buffer.read_pod<float32>();
    linear_damping = buffer.read_pod<float32>();
    mass = buffer.read_pod<float32>();
    buffer.skip(4);
}

