    out << "max_angular_velocity: " << max_angular_velocity << "\n";
    out << "floating_bobble: " << floating_bobble << "\n";
    out << "center_of_mass: \n";
    center_of_mass.print(out);
    out << "\n";
    out << "debris_quality: " << debris_quality << "\n";
    out << "max_linear_velocity: " << max_linear_velocity << "\n";
    out << "drag: " << drag << "\n";
    out << "override_layer: " << override_layer << "\n";
