void ADFTypes::CNpcSupportItemLaserHeadgearData::read(IO::File& buffer) {
    ParentCNpcSupportItem = std::move(Deferred::read(buffer));
    horizontal_angle = buffer.read_pod<float32>();
    firing_style = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    damage_initial = buffer.read_pod<float32>();
    damage_per_second = buffer.read_pod<float32>();
    shatter = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        spell_id = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    stagger = buffer.read_pod<float32>();
    number_of_lasers = buffer.read_pod<int32>();
    damage_type = buffer.read_pod<int32>();
    vertical_angle = buffer.read_pod<float32>();
    max_laser_distance = buffer.read_pod<float32>();
    comb_spacing = buffer.read_pod<float32>();
}

void ADFTypes::CNpcSupportItemLaserHeadgearData::print(std::ostream &out) const {
    out << "ParentCNpcSupportItem: " << "\n";
    if (ParentCNpcSupportItem) {
        ParentCNpcSupportItem->print(out);
    }
    out << "horizontal_angle: " << horizontal_angle << "\n";
    out << "firing_style: " << firing_style << "\n";
    out << "name: " << name << "\n";
    out << "damage_initial: " << damage_initial << "\n";
    out << "damage_per_second: " << damage_per_second << "\n";
    out << "shatter: " << shatter << "\n";
    out << "spell_id: " << spell_id << "\n";
    out << "stagger: " << stagger << "\n";
    out << "number_of_lasers: " << number_of_lasers << "\n";
    out << "damage_type: " << damage_type << "\n";
    out << "vertical_angle: " << vertical_angle << "\n";
    out << "max_laser_distance: " << max_laser_distance << "\n";
    out << "comb_spacing: " << comb_spacing << "\n";
}

nlohmann::json ADFTypes::CNpcSupportItemLaserHeadgearData::to_json() const {
    nlohmann::json _res;
    if (ParentCNpcSupportItem) {
        _res["ParentCNpcSupportItem"] = ParentCNpcSupportItem->to_json();
    }
    _res["horizontal_angle"] = horizontal_angle;
    _res["firing_style"] = firing_style;
    _res["name"] = name;
    _res["damage_initial"] = damage_initial;
    _res["damage_per_second"] = damage_per_second;
    _res["shatter"] = shatter;
    _res["spell_id"] = spell_id;
    _res["stagger"] = stagger;
    _res["number_of_lasers"] = number_of_lasers;
    _res["damage_type"] = damage_type;
    _res["vertical_angle"] = vertical_angle;
    _res["max_laser_distance"] = max_laser_distance;
    _res["comb_spacing"] = comb_spacing;
    return _res;
}

