void ADFTypes::CPlayerStateTrackerData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    disable_force_combat_ready_event.read(buffer);
    on_ground_combat_state = buffer.read_pod<uint32>();
    buffer.skip(4);
    on_ground_combat_enter.read(buffer);
    disable_contextual_idle_event.read(buffer);
    time_since_last_agression_action_key = buffer.read_pod<uint32>();
    safe_mode_modifier_name = buffer.read_pod<uint32>();
    time_until_safe_mode = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        enable_contextual_idle_act = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    on_ground_combat_exit.read(buffer);
    character_ref.read(buffer);
    time_since_last_combat_state_key = buffer.read_pod<uint32>();
    buffer.skip(4);
    vehicle_combat_enter.read(buffer);
    reset_state_counters.read(buffer);
    on_ground_target_counter = buffer.read_pod<uint32>();
    buffer.skip(4);
    vehicle_combat_exit.read(buffer);
    enable_force_combat_ready_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        enable_no_aggression_allowed_act = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        disable_contextual_idle_act = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    vehicle_combat_state = buffer.read_pod<uint32>();
    buffer.skip(4);
    disable_no_aggression_allowed_event.read(buffer);
    enable_contextual_idle_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enemy_range_for_disengage_combat_ready = buffer.read_pod<float32>();
    no_aggression_allowed_state_key = buffer.read_pod<uint32>();
    combat_ready_state = buffer.read_pod<uint32>();
    buffer.skip(4);
    enable_no_aggression_allowed_event.read(buffer);
    enemy_range_for_engage_combat_ready = buffer.read_pod<float32>();
    buffer.skip(4);
}

