void ADFTypes::CSoundModuleControllerGOData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    CSoundModuleSendFunctionArray.read(buffer);
    CSoundModuleFMODEventFunctionArray.read(buffer);
    SSoundModuleControllerAttachBoneArray.read(buffer);
    SSoundModuleControllerAttachPoint = std::move(Deferred::read(buffer));
    SSoundVariableOnScreen = std::move(Deferred::read(buffer));
    SSoundVariableHealthAndLifecycle = std::move(Deferred::read(buffer));
    SSoundVariableGroundSlopeAngle = std::move(Deferred::read(buffer));
    SSoundVariableWaterDepth = std::move(Deferred::read(buffer));
    SSoundVariableHeightDiff = std::move(Deferred::read(buffer));
    SSoundVariableRelativeVelocity = std::move(Deferred::read(buffer));
    SSoundVariableRelativeAngle = std::move(Deferred::read(buffer));
    SSoundVariableAngleArcRelationship = std::move(Deferred::read(buffer));
    SSoundVariableRelativeMovementAngle = std::move(Deferred::read(buffer));
    SSoundVariableAngle = std::move(Deferred::read(buffer));
    SSoundAddTagsArray.read(buffer);
    SSoundAcousticsProxy = std::move(Deferred::read(buffer));
    SSoundVariableInitArray.read(buffer);
    SSoundAddTagArray.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        module = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    static_ = buffer.read_pod<uint8>();
    collect_controllers_on_enabled = buffer.read_pod<uint8>();
    buffer.skip(6);
    event_collect_controllers.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        controller_preset = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_on_created.read(buffer);
    event_create.read(buffer);
    _exportable = buffer.read_pod<int32>();
    buffer.skip(4);
    event_disable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        controller_type = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    event_enable.read(buffer);
    release_on_disabled = buffer.read_pod<uint8>();
    create_on_enabled = buffer.read_pod<uint8>();
    buffer.skip(6);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    enabled = buffer.read_pod<uint8>();
    release_when_inactive = buffer.read_pod<uint8>();
    buffer.skip(6);
    event_release.read(buffer);
    max_controllers = buffer.read_pod<int32>();
    controller_stealing_priority = buffer.read_pod<int32>();
}

