void ADFTypes::CharacterAirMovementSettings::read(IO::File& buffer) {
    Gravity = buffer.read_pod<float32>();
    MaxVelocity = buffer.read_pod<float32>();
    MaxVelocityXZ = buffer.read_pod<float32>();
    ClampVelocitySpeed = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        Lift[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        DragX[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        DragY[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        DragZ[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        LiftPoint[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        PitchLimit[i] = buffer.read_pod<float32>();
    }
    YawSteerAmount = buffer.read_pod<float32>();
    DrawDebugLines = buffer.read_pod<uint32>();
    RotateCharYawToVelocity.read(buffer);
    RotateCharPitchToVelocity.read(buffer);
    PitchInputSpring.read(buffer);
    YawInputSpring.read(buffer);
    RollInputSpring.read(buffer);
    for(int i = 0; i < 3; ++i) {
        XInputYawPitchRollAmount[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        YInputYawPitchRollAmount[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        XLookYawPitchRollAmount[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        YLookYawPitchRollAmount[i] = buffer.read_pod<float32>();
    }
    RotateCharYawToSlingshot.read(buffer);
    for(int i = 0; i < 3; ++i) {
        PersistYawPitchRoll[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        CenterYawPitchRoll[i] = buffer.read_pod<float32>();
    }
    LiftInputSpring.read(buffer);
    DragInputSpring.read(buffer);
    AnimInputSpringX.read(buffer);
    AnimInputSpringY.read(buffer);
    NearGroundLiftDistance = buffer.read_pod<float32>();
    NearGroundMaxLift = buffer.read_pod<float32>();
    NearGroundLiftExponent = buffer.read_pod<float32>();
    NearGroundLiftDecayMax = buffer.read_pod<float32>();
    NearGroundLiftDecayMultiplier = buffer.read_pod<float32>();
    NearGroundLiftRecoverRate = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        LookSteerDeadZone[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        LookSteerMaxSpeed[i] = buffer.read_pod<float32>();
    }
    LookSteerMaxYaw = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        LookSteerMaxPitch[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        LookSteerExponential[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        LookSteerAimingDeadZone[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        LookSteerAimingMaxSpeed[i] = buffer.read_pod<float32>();
    }
    LookSteerAimingMaxYaw = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        LookSteerAimingMaxPitch[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        LookSteerAimingExponential[i] = buffer.read_pod<float32>();
    }
    SlingshotPitchAdjust = buffer.read_pod<float32>();
    SlingshotExtraLift = buffer.read_pod<float32>();
    SlingshotDirectAccel = buffer.read_pod<float32>();
    SlingshotForwardAccel = buffer.read_pod<float32>();
    SlingshotMaxSpeedAdjust = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        SlingshotDragXYZAdjust[i] = buffer.read_pod<float32>();
    }
    SlingshotBreakPitch = buffer.read_pod<float32>();
    SlingshotBreakYawStart = buffer.read_pod<float32>();
    SlingshotBreakYawEnd = buffer.read_pod<float32>();
    SlingshotBreakYawBlendTime = buffer.read_pod<float32>();
    SlingshotBreakDistance = buffer.read_pod<float32>();
    RetractSlingshotSettings.read(buffer);
}

