void ADFTypes::CAIAirTrafficSplineData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    altitude_type = buffer.read_pod<int32>();
    spline_backwards = buffer.read_pod<uint8>();
    buffer.skip(3);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    authority_only = buffer.read_pod<uint8>();
    buffer.skip(7);
    spline.read(buffer);
}

void ADFTypes::CAIAirTrafficSplineData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "altitude_type: " << altitude_type << "\n";
    out << "spline_backwards: " << spline_backwards << "\n";
    out << "name: " << name << "\n";
    out << "authority_only: " << authority_only << "\n";
    out << "spline: \n";
    spline.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::CAIAirTrafficSplineData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    _res["altitude_type"] = altitude_type;
    _res["spline_backwards"] = spline_backwards;
    _res["name"] = name;
    _res["authority_only"] = authority_only;
    _res["spline"] = spline.to_json();
    return _res;
}

