void ADFTypes::CDamageableData::read(IO::File& buffer) {
    ParentCPhysicsObject = std::move(Deferred::read(buffer));
    SDamageTypeResponderArray.read(buffer);
    SArmorInfoArray.read(buffer);
    SHealthDecreasedEventArray.read(buffer);
    damageable_shield_ref.read(buffer);
    on_hit.read(buffer);
    on_hit_damaged.read(buffer);
    ShieldingFOVObject.read(buffer);
    force_despawn.read(buffer);
    chaos = buffer.read_pod<int32>();
    buffer.skip(4);
    on_world_at_war_destroy.read(buffer);
    enter_victor_mode.read(buffer);
    health = buffer.read_pod<float32>();
    buffer.skip(4);
    damageable_health_regainpool_ref.read(buffer);
    core_health_segments = buffer.read_pod<int32>();
    buffer.skip(4);
    restore_health.read(buffer);
    on_hit_not_damaged.read(buffer);
    drop_to_one_hp.read(buffer);
    on_removed.read(buffer);
    make_invulnerable.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    make_vulnerable.read(buffer);
    exit_victor_mode.read(buffer);
    on_annihilated.read(buffer);
    on_destroy.read(buffer);
    force_destroy.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        health_difficulty_parameter = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    invulnerable = buffer.read_pod<uint8>();
    buffer.skip(7);
    on_shield_absorbed_damage.read(buffer);
    victor_mode = buffer.read_pod<uint8>();
    buffer.skip(7);
}

void ADFTypes::CDamageableData::print(std::ostream &out) const {
    out << "ParentCPhysicsObject: " << "\n";
    if (ParentCPhysicsObject) {
        ParentCPhysicsObject->print(out);
    }
    out << "SDamageTypeResponderArray: \n";
    SDamageTypeResponderArray.print(out);
    out << "\n";
    out << "SArmorInfoArray: \n";
    SArmorInfoArray.print(out);
    out << "\n";
    out << "SHealthDecreasedEventArray: \n";
    SHealthDecreasedEventArray.print(out);
    out << "\n";
    damageable_shield_ref.print(out);
    on_hit.print(out);
    on_hit_damaged.print(out);
    ShieldingFOVObject.print(out);
    force_despawn.print(out);
    out << "chaos: " << chaos << "\n";
    on_world_at_war_destroy.print(out);
    enter_victor_mode.print(out);
    out << "health: " << health << "\n";
    damageable_health_regainpool_ref.print(out);
    out << "core_health_segments: " << core_health_segments << "\n";
    restore_health.print(out);
    on_hit_not_damaged.print(out);
    drop_to_one_hp.print(out);
    on_removed.print(out);
    make_invulnerable.print(out);
    out << "name: " << name << "\n";
    make_vulnerable.print(out);
    exit_victor_mode.print(out);
    on_annihilated.print(out);
    on_destroy.print(out);
    force_destroy.print(out);
    out << "health_difficulty_parameter: " << health_difficulty_parameter << "\n";
    out << "invulnerable: " << invulnerable << "\n";
    on_shield_absorbed_damage.print(out);
    out << "victor_mode: " << victor_mode << "\n";
}

