void ADFTypes::CConstraintVelocityMotorDataData::read(IO::File& buffer) {
    ForwardMotorEvent.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    MinForce = buffer.read_pod<float32>();
    UseVelocityTarget = buffer.read_pod<uint8>();
    buffer.skip(3);
    MaxForce = buffer.read_pod<float32>();
    buffer.skip(4);
    ReverseMotorEvent.read(buffer);
    InitialVelocityTargetDirForward = buffer.read_pod<uint8>();
    buffer.skip(3);
    Stiffness = buffer.read_pod<float32>();
    VelocityTarget = buffer.read_pod<float32>();
    buffer.skip(4);
}

