void ADFTypes::CNpcSupportItemThrownObjectData::read(IO::File& buffer) {
    ParentCNpcSupportItem = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        bb_key_throw_target_position = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    angular_speed = buffer.read_pod<float32>();
    specified_dir_max_throw_angle = buffer.read_pod<float32>();
    throw_in_specified_dir = buffer.read_pod<uint8>();
    buffer.skip(3);
    gravity = buffer.read_pod<float32>();
    max_aim_angle = buffer.read_pod<float32>();
    throw_in_velocity_distance = buffer.read_pod<float32>();
    for(int i = 0; i < 16; ++i) {
        throw_offset[i] = buffer.read_pod<float32>();
    }
    specified_dir_min_throw_distance = buffer.read_pod<float32>();
    throw_in_velocity_dir = buffer.read_pod<uint8>();
    buffer.skip(3);
    specified_dir_min_throw_angle = buffer.read_pod<float32>();
    skip_max_aim_angle = buffer.read_pod<uint8>();
    buffer.skip(3);
    throw_speed = buffer.read_pod<float32>();
    specified_dir_max_throw_distance = buffer.read_pod<float32>();
}

