void ADFTypes::SSoundAcousticsProxyData::read(IO::File& buffer) {
    obstruction_shape = buffer.read_pod<int32>();
    obstruction_max = buffer.read_pod<float32>();
    reflective_path_max = buffer.read_pod<float32>();
    ray_cast_distance_min = buffer.read_pod<float32>();
    direct_path_max_delta = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        obstruction_aabb_scalar_min[i] = buffer.read_pod<float32>();
    }
    reflective_path_max_delta = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        has_direct_path_within_projection_variable = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        direct_path_aabb_translation[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        has_direct_path_variable = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    _exportable = buffer.read_pod<int32>();
    obstruction_max_delta = buffer.read_pod<float32>();
    ray_cast_distance_max = buffer.read_pod<float32>();
    direct_path_projection_scalar = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        direct_path_aabb_scalar[i] = buffer.read_pod<float32>();
    }
    use_reverb_send_distance_scaling = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 3; ++i) {
        obstruction_aabb_scalar_max[i] = buffer.read_pod<float32>();
    }
    reflective_path_at_max_distance = buffer.read_pod<float32>();
    direct_path_max = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ray_cast_urgency = buffer.read_pod<int32>();
    direct_path_at_max_distance = buffer.read_pod<float32>();
}

void ADFTypes::SSoundAcousticsProxyData::print(std::ostream &out) const {
    out << "obstruction_shape: " << obstruction_shape << "\n";
    out << "obstruction_max: " << obstruction_max << "\n";
    out << "reflective_path_max: " << reflective_path_max << "\n";
    out << "ray_cast_distance_min: " << ray_cast_distance_min << "\n";
    out << "direct_path_max_delta: " << direct_path_max_delta << "\n";
    out << "obstruction_aabb_scalar_min: \n";
    obstruction_aabb_scalar_min.print(out);
    out << "\n";
    out << "reflective_path_max_delta: " << reflective_path_max_delta << "\n";
    out << "has_direct_path_within_projection_variable: " << has_direct_path_within_projection_variable << "\n";
    out << "direct_path_aabb_translation: \n";
    direct_path_aabb_translation.print(out);
    out << "\n";
    out << "has_direct_path_variable: " << has_direct_path_variable << "\n";
    out << "_exportable: " << _exportable << "\n";
    out << "obstruction_max_delta: " << obstruction_max_delta << "\n";
    out << "ray_cast_distance_max: " << ray_cast_distance_max << "\n";
    out << "direct_path_projection_scalar: " << direct_path_projection_scalar << "\n";
    out << "direct_path_aabb_scalar: \n";
    direct_path_aabb_scalar.print(out);
    out << "\n";
    out << "use_reverb_send_distance_scaling: " << use_reverb_send_distance_scaling << "\n";
    out << "obstruction_aabb_scalar_max: \n";
    obstruction_aabb_scalar_max.print(out);
    out << "\n";
    out << "reflective_path_at_max_distance: " << reflective_path_at_max_distance << "\n";
    out << "direct_path_max: " << direct_path_max << "\n";
    out << "name: " << name << "\n";
    out << "ray_cast_urgency: " << ray_cast_urgency << "\n";
    out << "direct_path_at_max_distance: " << direct_path_at_max_distance << "\n";
}

nlohmann::json ADFTypes::SSoundAcousticsProxyData::to_json() const {
    nlohmann::json _res;
    _res["obstruction_shape"] = obstruction_shape;
    _res["obstruction_max"] = obstruction_max;
    _res["reflective_path_max"] = reflective_path_max;
    _res["ray_cast_distance_min"] = ray_cast_distance_min;
    _res["direct_path_max_delta"] = direct_path_max_delta;
    _res["obstruction_aabb_scalar_min"] = obstruction_aabb_scalar_min.to_json();
    _res["reflective_path_max_delta"] = reflective_path_max_delta;
    _res["has_direct_path_within_projection_variable"] = has_direct_path_within_projection_variable;
    _res["direct_path_aabb_translation"] = direct_path_aabb_translation.to_json();
    _res["has_direct_path_variable"] = has_direct_path_variable;
    _res["_exportable"] = _exportable;
    _res["obstruction_max_delta"] = obstruction_max_delta;
    _res["ray_cast_distance_max"] = ray_cast_distance_max;
    _res["direct_path_projection_scalar"] = direct_path_projection_scalar;
    _res["direct_path_aabb_scalar"] = direct_path_aabb_scalar.to_json();
    _res["use_reverb_send_distance_scaling"] = use_reverb_send_distance_scaling;
    _res["obstruction_aabb_scalar_max"] = obstruction_aabb_scalar_max.to_json();
    _res["reflective_path_at_max_distance"] = reflective_path_at_max_distance;
    _res["direct_path_max"] = direct_path_max;
    _res["name"] = name;
    _res["ray_cast_urgency"] = ray_cast_urgency;
    _res["direct_path_at_max_distance"] = direct_path_at_max_distance;
    return _res;
}

