void ADFTypes::SCharacterGibInfoData::read(IO::File& buffer) {
    SCharacterGibInfoSphereArray.read(buffer);
    only_gib_by_alias = buffer.read_pod<uint8>();
    gibbable_post_mortem = buffer.read_pod<uint8>();
    only_for_promotion = buffer.read_pod<uint8>();
    destroy_vocals_on_gib = buffer.read_pod<uint8>();
    gib_max_chance = buffer.read_pod<float32>();
    promotion_name = buffer.read_pod<uint32>();
    gib_alias = buffer.read_pod<uint32>();
    hitzone_name = buffer.read_pod<uint32>();
    drop_weapon_on_gib = buffer.read_pod<uint8>();
    gibbable_in_low_violence = buffer.read_pod<uint8>();
    dynamic_position = buffer.read_pod<uint8>();
    buffer.skip(1);
    gib_min_chance = buffer.read_pod<float32>();
    buffer.skip(4);
    force_gib_event.read(buffer);
    gib_max_threshold = buffer.read_pod<float32>();
    buffer.skip(4);
    disable_gib_event.read(buffer);
    valid_on_electric_damage = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        gib_effect_usage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    gib_min_threshold = buffer.read_pod<float32>();
    accumulated_gibfactor_usage = buffer.read_pod<float32>();
    counts_as_rupture = buffer.read_pod<uint8>();
    buffer.skip(7);
    force_kill_gib_event.read(buffer);
    un_gib_event.read(buffer);
    on_gib_event.read(buffer);
    num_shapes_to_keep = buffer.read_pod<int32>();
    valid_on_wingstick_damage = buffer.read_pod<uint8>();
    buffer.skip(3);
}

