    Rebel = buffer.read_pod<uint8>();
    buffer.skip(6);
    disable_event.read(buffer);
    max_occupants = buffer.read_pod<int32>();
    buffer.skip(4);
    on_start_event.read(buffer);
    weapon_needed = buffer.read_pod<uint8>();
    buffer.skip(3);
    parent_interest_reaction_type = buffer.read_pod<int32>();
    staged_only_once = buffer.read_pod<uint8>();
    buffer.skip(3);
    cooldown_min = buffer.read_pod<float32>();
    Blackhand = buffer.read_pod<uint8>();
    Male = buffer.read_pod<uint8>();
    staged_only = buffer.read_pod<uint8>();
    buffer.skip(5);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Soldier = buffer.read_pod<uint8>();
    buffer.skip(3);
    cooldown_max = buffer.read_pod<float32>();
