void ADFTypes::CNetworkRandomizerData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    SNetworkRandomEventArray.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    reset_randomizer.read(buffer);
    dont_send_on_selected_event_on_init = buffer.read_pod<uint8>();
    disable_after_randomized = buffer.read_pod<uint8>();
    buffer.skip(6);
    randomize.read(buffer);
    amount_to_select = buffer.read_pod<int32>();
    buffer.skip(4);
}

