void ADFTypes::CPhysicalProjectileWeaponData::read(IO::File& buffer) {
    ParentCWeaponBase = std::move(Deferred::read(buffer));
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        target_indication_effect = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    impact_effect_table.read(buffer);
    trail_effect_ai = buffer.read_pod<int32>();
    buffer.skip(4);
    trail_sound_player.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        physical_projectile_collision_model = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    trail_sound_ai.read(buffer);
    for(int i = 0; i < 3; ++i) {
        trail_position[i] = buffer.read_pod<float32>();
    }
    trail_effect_player = buffer.read_pod<int32>();
}

