void ADFTypes::HintModifierParams::read(IO::File& buffer) {
    BypassModifier = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 4; ++i) {
        HintHashes[i] = buffer.read_pod<uint32>();
    }
    for(int i = 0; i < 3; ++i) {
        DeltaPivotOffset[i] = buffer.read_pod<float32>();
    }
    DeltaPitch = buffer.read_pod<float32>();
    DeltaYaw = buffer.read_pod<float32>();
    DeltaRoll = buffer.read_pod<float32>();
    DeltaAzimuth = buffer.read_pod<float32>();
    DeltaElevation = buffer.read_pod<float32>();
    DeltaDistance = buffer.read_pod<float32>();
    BlendInSpring.read(buffer);
    BlendOutSpring.read(buffer);
    DrawDebug = buffer.read_pod<uint8>();
    buffer.skip(3);
}

