    impact_armor = buffer.read_pod<int32>();
    impact_armor_strength = buffer.read_pod<float32>();
    fire_armor = buffer.read_pod<int32>();
    fire_armor_strength = buffer.read_pod<float32>();
    melee_armor = buffer.read_pod<int32>();
    melee_armor_strength = buffer.read_pod<float32>();
    electricity_armor = buffer.read_pod<int32>();
    electricity_armor_strength = buffer.read_pod<float32>();
    grapple_pull_armor = buffer.read_pod<int32>();
    grapple_pull_armor_strength = buffer.read_pod<float32>();
