    deform_scale = buffer.read_pod<float32>();
    damaged_threshold = buffer.read_pod<float32>();
    block_parts_damage_use_threshold = buffer.read_pod<int8>();
    buffer.skip(1);
    block_parts_damage_health_threshold = buffer.read_pod<int16>();
    explosion_delay_s = buffer.read_pod<uint16>();
    burn_duration_s = buffer.read_pod<uint16>();
    vulnerable_duration_s = buffer.read_pod<uint16>();
    buffer.skip(2);
