void ADFTypes::VegetationModel::read(IO::File& buffer) {
    ModelIndex = buffer.read_pod<uint16>();
    ModelHandle = buffer.read_pod<uint16>();
    ModelExtraLodsHandle = buffer.read_pod<uint16>();
    ShadowCascadeLimit = buffer.read_pod<uint8>();
    LodCount = buffer.read_pod<int8>();
    LodFactor = buffer.read_pod<float32>();
    LodBias = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        HalfExtents[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        ForestColor[i] = buffer.read_pod<uint8>();
    }
    buffer.skip(1);
    ModelFilenameHash.read(buffer);
    ModelExtraLodsFilenameHash.read(buffer);
    Impostor = buffer.read_pod<int16>();
    UseBillboard = buffer.read_pod<uint8>();
    FarLayer = buffer.read_pod<uint8>();
    for(int i = 0; i < 2; ++i) {
        BillboardSize[i] = buffer.read_pod<float32>();
    }
    SwayFactor = buffer.read_pod<float32>();
    FitRootsToTerrain = buffer.read_pod<uint8>();
    buffer.skip(3);
    RootRadius = buffer.read_pod<float32>();
    GlobalIlluminationMask = buffer.read_pod<uint8>();
    AlphaBlendLodMask = buffer.read_pod<uint8>();
    AlphaFadeLodMask = buffer.read_pod<uint8>();
    for(int i = 0; i < 5; ++i) {
        AlphaThreshold[i] = buffer.read_pod<uint8>();
    }
    AlphaMultiplier = buffer.read_pod<float32>();
    NormalFadeDistance = buffer.read_pod<float32>();
    NormalBendNear = buffer.read_pod<float32>();
    NormalBendFar = buffer.read_pod<float32>();
    SphereNormalFadeInStart = buffer.read_pod<float32>();
    SphereNormalFadeInEnd = buffer.read_pod<float32>();
    SkyOcclusionIntensity = buffer.read_pod<float32>();
    CullShadowScale = buffer.read_pod<float32>();
    CullRSMScale = buffer.read_pod<float32>();
    Flags = buffer.read_pod<uint32>();
}

