void ADFTypes::CSoundModuleEntityGameObjectData::read(IO::File& buffer) {
    ParentCSoundModuleGameObject = std::move(Deferred::read(buffer));
    SSoundModuleVariablesArray.read(buffer);
    max_dynamic_variables = buffer.read_pod<int32>();
    self_reset_delay = buffer.read_pod<float32>();
    max_controllers = buffer.read_pod<int32>();
    _exportable = buffer.read_pod<int32>();
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        audible_rank_variable = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    update_audible_rank = buffer.read_pod<uint8>();
    buffer.skip(7);
}

