void ADFTypes::CDespawnVolumeData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    ParentCTransformable = std::move(Deferred::read(buffer));
    for(int i = 0; i < 16; ++i) {
        throw std::runtime_error("Unsupported inline array inner type");
    }
    faction_all_hostile = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        timestamp_condition_bb_key = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    networked = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    faction = buffer.read_pod<int32>();
    character_is_dead = buffer.read_pod<uint8>();
    buffer.skip(3);
    timestamp_condition_time = buffer.read_pod<float32>();
    ignore_player = buffer.read_pod<uint8>();
    weapons = buffer.read_pod<uint8>();
    buffer.skip(2);
    despawn_event.read(buffer);
    characters = buffer.read_pod<uint8>();
    debris = buffer.read_pod<uint8>();
    other_spawned = buffer.read_pod<uint8>();
    buffer.skip(5);
}

void ADFTypes::CDespawnVolumeData::print(std::ostream &out) const {
    out << "ParentCGameObject: " << "\n";
    if (ParentCGameObject) {
        ParentCGameObject->print(out);
    }
    out << "ParentCTransformable: " << "\n";
    if (ParentCTransformable) {
        ParentCTransformable->print(out);
    }
    out << "SShapeDefArray: \n";
    SShapeDefArray.print(out);
    out << "\n";
    out << "faction_all_hostile: " << faction_all_hostile << "\n";
    out << "timestamp_condition_bb_key: " << timestamp_condition_bb_key << "\n";
    out << "networked: " << networked << "\n";
    out << "name: " << name << "\n";
    out << "faction: " << faction << "\n";
    out << "character_is_dead: " << character_is_dead << "\n";
    out << "timestamp_condition_time: " << timestamp_condition_time << "\n";
    out << "ignore_player: " << ignore_player << "\n";
    out << "weapons: " << weapons << "\n";
    despawn_event.print(out);
    out << "characters: " << characters << "\n";
    out << "debris: " << debris << "\n";
    out << "other_spawned: " << other_spawned << "\n";
}

nlohmann::json ADFTypes::CDespawnVolumeData::to_json() const {
    nlohmann::json _res;
    if (ParentCGameObject) {
        _res["ParentCGameObject"] = ParentCGameObject->to_json();
    }
    if (ParentCTransformable) {
        _res["ParentCTransformable"] = ParentCTransformable->to_json();
    }
    _res["SShapeDefArray"] = SShapeDefArray.to_json();
    _res["faction_all_hostile"] = faction_all_hostile;
    _res["timestamp_condition_bb_key"] = timestamp_condition_bb_key;
    _res["networked"] = networked;
    _res["name"] = name;
    _res["faction"] = faction;
    _res["character_is_dead"] = character_is_dead;
    _res["timestamp_condition_time"] = timestamp_condition_time;
    _res["ignore_player"] = ignore_player;
    _res["weapons"] = weapons;
    _res["despawn_event"] = despawn_event.to_json();
    _res["characters"] = characters;
    _res["debris"] = debris;
    _res["other_spawned"] = other_spawned;
    return _res;
}

