void ADFTypes::SSoundAcousticRoomData::read(IO::File& buffer) {
    SSoundAcousticRoomFunctionArray.read(buffer);
    SSoundAcousticRoomSnapshotArray.read(buffer);
    SSoundAcousticRoomFmodEvent = std::move(Deferred::read(buffer));
    for(int i = 0; i < 2; ++i) {
        automated_reverbtime_range[i] = buffer.read_pod<float32>();
    }
    automated_earlydelay_distance_max = buffer.read_pod<float32>();
    room_tone_play_behaviour = buffer.read_pod<int32>();
    occlusion_gain_blend_mode = buffer.read_pod<int32>();
    automated_reverbtime_size_max = buffer.read_pod<float32>();
    release_time = buffer.read_pod<float32>();
    obstruction_when_stacked = buffer.read_pod<float32>();
    automated_reverbtime_size_min = buffer.read_pod<float32>();
    occlusion_gain_obstruction = buffer.read_pod<float32>();
    occlusion_gain_reflective_path = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        room_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 2; ++i) {
        automated_earlydelay_range[i] = buffer.read_pod<float32>();
    }
    hold_time = buffer.read_pod<float32>();
    stack_priority = buffer.read_pod<int32>();
    occlusion_gain_direct_path = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    obstruction_when_outside = buffer.read_pod<float32>();
    buffer.skip(4);
    tap_sound.read(buffer);
    automated_earlydelay_distance_min = buffer.read_pod<float32>();
    buffer.skip(4);
}

