void ADFTypes::WeaponAITuningBase::read(IO::File& buffer) {
    position_range_near = buffer.read_pod<float32>();
    position_range_mid_near = buffer.read_pod<float32>();
    position_range_mid_far = buffer.read_pod<float32>();
    position_range_far = buffer.read_pod<float32>();
    effective_range_profiles.read(buffer);
    burst_ranges.read(buffer);
    min_accuracy_to_shoot = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        dropped_magazines[i] = buffer.read_pod<int32>();
    }
    buffer.skip(4);
    ai_accuracy_stats_tuning.read(buffer);
    ai_target_lag.read(buffer);
    buffer.skip(4);
}

