void ADFTypes::CTimeTriggerData::read(IO::File& buffer) {
    ParentCGameObject = std::move(Deferred::read(buffer));
    STimerComponentArray.read(buffer);
    show_event.read(buffer);
    time_to_add = buffer.read_pod<float32>();
    buffer.skip(4);
    enable_event.read(buffer);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        text = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    visible = buffer.read_pod<uint8>();
    buffer.skip(3);
    time_max = buffer.read_pod<float32>();
    hide_event.read(buffer);
    expired_event.read(buffer);
    add_time_event.read(buffer);
    disable_event.read(buffer);
    stop_event.read(buffer);
    delay_between_instances_high = buffer.read_pod<float32>();
    max_distributed_delay_high = buffer.read_pod<float32>();
    active = buffer.read_pod<uint8>();
    use_real_time = buffer.read_pod<uint8>();
    buffer.skip(6);
    start_event.read(buffer);
    max_distributed_delay_low = buffer.read_pod<float32>();
    buffer.skip(4);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    delay_between_instances_low = buffer.read_pod<float32>();
    bar = buffer.read_pod<uint8>();
    reverse = buffer.read_pod<uint8>();
    enabled = buffer.read_pod<uint8>();
    buffer.skip(1);
    restart_event.read(buffer);
    shared_id = buffer.read_pod<uint32>();
    time = buffer.read_pod<float32>();
    loop = buffer.read_pod<uint8>();
    buffer.skip(7);
}

