void ADFTypes::CAOVolumeObjectData::read(IO::File& buffer) {
    ParentCScaleTransformable = std::move(Deferred::read(buffer));
    ParentCGameObject = std::move(Deferred::read(buffer));
    SEnvironmentTagListener = std::move(Deferred::read(buffer));
    layer = buffer.read_pod<int32>();
    directionality_z = buffer.read_pod<float32>();
    max_ao = buffer.read_pod<float32>();
    intensity = buffer.read_pod<float32>();
    blend_mode = buffer.read_pod<int32>();
    tag_fade = buffer.read_pod<float32>();
    falloff_z = buffer.read_pod<float32>();
    falloff_x = buffer.read_pod<float32>();
    falloff_y = buffer.read_pod<float32>();
    buffer.skip(4);
    enable_on_event.read(buffer);
    gradient_type_y = buffer.read_pod<int32>();
    gradient_type_x = buffer.read_pod<int32>();
    gradient_type_z = buffer.read_pod<int32>();
    buffer.skip(4);
    receive_matrix_event.read(buffer);
    directionality_y = buffer.read_pod<float32>();
    directionality_x = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        taper_z[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        offset[i] = buffer.read_pod<float32>();
    }
    directionality_mode = buffer.read_pod<int32>();
    need_updates = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        std::streamoff original_offset = buffer.get_position();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    disable_on_event.read(buffer);
    enabled = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 2; ++i) {
        taper_y[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        taper_x[i] = buffer.read_pod<float32>();
    }
    RainOccluder = buffer.read_pod<uint8>();
    buffer.skip(3);
}

