void ADFTypes::MapIcon::read(IO::File& buffer) {
    ID = buffer.read_pod<uint64>();
    FastTravelId = buffer.read_pod<uint64>();
    for(int i = 0; i < 3; ++i) {
        Position[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    EnableEvent.read(buffer);
    DisableEvent.read(buffer);
    ShowEvent.read(buffer);
    HideEvent.read(buffer);
    OnShowEvent.read(buffer);
    OnHideEvent.read(buffer);
    OnSelectedEvent.read(buffer);
    DisableIconOverride.read(buffer);
    CustomName = buffer.read_pod<uint32>();
    BlinkOnShow = buffer.read_pod<uint8>();
    buffer.skip(3);
    BlinkOnEvent.read(buffer);
    ClampToEdgeDistanceSq = buffer.read_pod<float32>();
    TinBlendStart = buffer.read_pod<float32>();
    TinBlendEnd = buffer.read_pod<float32>();
    Type = buffer.read_pod<int8>();
    Enabled = buffer.read_pod<uint8>();
    Global = buffer.read_pod<uint8>();
    Visible = buffer.read_pod<uint8>();
    ClampToEdge = buffer.read_pod<uint8>();
    Minimap = buffer.read_pod<uint8>();
    buffer.skip(2);
    MinimapShowDistanceSqStart = buffer.read_pod<float32>();
    MinimapShowDistanceSqEnd = buffer.read_pod<float32>();
    Worldmap = buffer.read_pod<uint8>();
    ShowDirection = buffer.read_pod<uint8>();
    MapZoomedIn = buffer.read_pod<uint8>();
    MapZoomedOut = buffer.read_pod<uint8>();
    TargetIndicator = buffer.read_pod<uint8>();
    ClampToScreen = buffer.read_pod<uint8>();
    AutoRouteGPS = buffer.read_pod<uint8>();
    Replicate = buffer.read_pod<uint8>();
    Dynamic = buffer.read_pod<uint8>();
    Save = buffer.read_pod<uint8>();
    SavePosition = buffer.read_pod<uint8>();
    Resetable = buffer.read_pod<uint8>();
    Region = buffer.read_pod<uint32>();
    ShowOnDistanceSq = buffer.read_pod<float32>();
    IconAlias = buffer.read_pod<uint32>();
    DrawOrder = buffer.read_pod<int8>();
    buffer.skip(3);
    SplinesInfo.read(buffer);
    ShapesInfo.read(buffer);
    for(int i = 0; i < 4; ++i) {
        ShapeColor[i] = buffer.read_pod<float32>();
    }
    DrawIconOverShape = buffer.read_pod<uint8>();
    buffer.skip(3);
    MissionId = buffer.read_pod<uint32>();
    ObjectiveId = buffer.read_pod<uint32>();
    buffer.skip(4);
    GpsTargetPositions.read(buffer);
    ScriptTags.read(buffer);
    World = buffer.read_pod<uint32>();
    buffer.skip(4);
}

