    ParticleModifiers.read(buffer);
    EmitterLifetimeIndex = buffer.read_pod<uint32>();
    StartTime = buffer.read_pod<uint32>();
    AliveInstantiators.read(buffer);
    OnDeathInstantiators.read(buffer);
    MaxParticles = buffer.read_pod<uint32>();
